# --- block: model ---
WIDTH = 256
N_STAGES = 5


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block, kept for the bottleneck only."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class DilatedResBlock(nn.Module):
    """Pre-activation dilated residual block: GN -> GELU -> dense k-tap dilated conv -> GN -> GELU -> 1x1 conv, added back
    with a learnable per-channel scale. Kernels are stored as 2-D matrices so Muon trains them."""

    def __init__(self, channels, dilation=1, k=3, residual_scale=0.15):
        super().__init__()
        self.c, self.k, self.dilation = channels, k, dilation
        self.norm1, self.norm2 = group_norm(channels), group_norm(channels)
        self.w1 = nn.Parameter(torch.empty(channels, channels * k))
        self.b1 = nn.Parameter(torch.zeros(channels))
        self.w2 = nn.Parameter(torch.empty(channels, channels))
        self.b2 = nn.Parameter(torch.zeros(channels))
        self.scale = nn.Parameter(torch.full((channels, 1), residual_scale))
        nn.init.trunc_normal_(self.w1, std=0.02)
        nn.init.trunc_normal_(self.w2, std=0.02)

    def forward(self, x):
        c = self.c
        y = F.gelu(self.norm1(x), approximate="tanh")
        y = F.conv1d(y, self.w1.view(c, c, self.k).to(y.dtype), self.b1.to(y.dtype),
                     padding=self.dilation * (self.k - 1) // 2, dilation=self.dilation)
        y = F.gelu(self.norm2(y), approximate="tanh")
        y = F.conv1d(y, self.w2.unsqueeze(-1).to(y.dtype), self.b2.to(y.dtype))
        return x + (y * self.scale.to(y.dtype)).to(x.dtype)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


ENC_DILATIONS = ((1, 2), (4, 8), (1, 2), (4, 8), (1, 2))
DEC_DILATIONS = (1, 4)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([nn.Sequential(*[DilatedResBlock(width, d) for d in ENC_DILATIONS[i]])
                                     for i in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[DilatedResBlock(width, d) for d in DEC_DILATIONS])
                                     for _ in range(n_stages)])

    def forward(self, z, skips):
        x = z
        for fuse, blocks, skip in zip(self.fuse, self.blocks, reversed(skips)):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = blocks(fuse(x, skip))
        return x


class ProfileHead(nn.Module):
    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        profile = self.profile_head(self.decoder(z, skips))
        return {"profile": profile, "counts": counts}


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's training loss (cherimoya.py fit + losses._mixture_loss): profile MNLL and count MSE on ln(total + 1),
    weighted by Kendall-Gal learned weights 1 / (2 s^2) with the regulariser (log s)^2. As in cherimoya, the weights stop
    learning after the first epoch in which the mean absolute gradient of s0 falls below 1."""

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def forward(self, out, y, is_peak, net):
        """`out` is the model's output dict, y (B, 1, 1000) raw targets, is_peak (B,) bool. Returns (loss, logs)."""
        profile_loss = mnll(out["profile"], y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        loss = profile_loss / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        return loss.sum(), {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach()}

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5
AUX_STAGES = 4   # decoder stages at 16, 8, 4, 2 bp get auxiliary profile heads


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block: 3-tap dilated depthwise conv, whole-plane layer norm, MLP C->2C->C added with scale 0.15."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    """CAPYBARA pre-activation conv block: norm -> GELU -> dropout -> conv."""

    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    """CAPYBARA HybridAttentionUnit: residual pair of conv blocks, then pre-norm self-attention and an MLP."""

    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([CheriBlock(width) for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=4):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    """CAPYBARA YCountHead: conv [128, 64] (k5, GN, GELU, dropout, max-pool 2), adaptive avg pool to 4 bins, MLP [64]."""

    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    """up + 2*sigmoid(W[up; skip])*skip, W a zero-initialised kernel-1 conv, so the gate starts at 1."""

    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    """Baseline decoder; the first AUX_STAGES stages (16, 8, 4, 2 bp) also emit zero-initialised kernel-1 profile logits."""

    def __init__(self, width=WIDTH, n_stages=N_STAGES, blocks_per_stage=2, aux_stages=AUX_STAGES):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[CheriBlock(width) for _ in range(blocks_per_stage)])
                                     for _ in range(n_stages)])
        self.aux_heads = nn.ModuleList()
        for _ in range(aux_stages):
            head = nn.Conv1d(width, 1, 1)
            nn.init.zeros_(head.weight)
            nn.init.zeros_(head.bias)
            self.aux_heads.append(head)
        self.n_stages = n_stages

    def forward(self, z, skips):
        x = z
        aux = []
        for i, (fuse, blocks, skip) in enumerate(zip(self.fuse, self.blocks, reversed(skips))):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = blocks(fuse(x, skip))
            if i < len(self.aux_heads):
                res = 2 ** (self.n_stages - 1 - i)
                aux.append((res, self.aux_heads[i](x)))
        return x, aux


class ProfileHead(nn.Module):
    """Cherimoya's profile head: one kernel-75 conv, then the central 1,000 positions."""

    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0
        # late count-trunk detach gate g (1 -> 0); set by the Objective from net.progress so compile never re-specialises
        self.register_buffer("count_gate", torch.ones(1), persistent=False)

    def forward(self, x):
        in_len = x.shape[-1]
        flank = (in_len - OUT_LEN) // 2
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        zd = z.detach()
        z_c = zd + self.count_gate.to(z.dtype) * (z - zd)
        counts = self.count_head(z_c)
        h, aux = self.decoder(z, skips)
        out = {"profile": self.profile_head(h), "counts": counts}
        for res, logits in aux:
            b0 = flank // res
            b1 = -(-(flank + OUT_LEN) // res)
            out["aux_%d" % res] = logits[..., b0:b1]
        return out


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's Kendall-Gal loss (profile MNLL + count MSE on ln(total+1)) plus decoder deep supervision: MNLL of the
    auxiliary 16/8/4/2 bp logits against the targets summed into the same bins (total weight 0.5, added to the profile
    term). Also drives the model's late count-trunk detach gate g: 1 until progress 0.72, linearly to 0 at 0.85."""

    AUX_WEIGHT = 0.5
    FLANK = 557                  # (2114 - 1000) // 2: offset of the central 1,000 bp in the input window
    DETACH_START, DETACH_END = 0.72, 0.85

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))
        self._last_gate = None

    def _binned(self, y, res, n_bins):
        left = self.FLANK % res
        right = n_bins * res - left - y.shape[-1]
        yp = nn.functional.pad(y.float(), (left, max(right, 0)))[..., :n_bins * res]
        return yp.reshape(y.shape[0], y.shape[1], n_bins, res).sum(-1)

    def _set_gate(self, net):
        p = float(getattr(net, "progress", 0.0))
        g = min(1.0, max(0.0, (self.DETACH_END - p) / (self.DETACH_END - self.DETACH_START)))
        if self._last_gate is not None and g == self._last_gate:
            return g
        gate = getattr(net, "count_gate", None)
        if gate is None and hasattr(net, "_orig_mod"):
            gate = getattr(net._orig_mod, "count_gate", None)
        if gate is not None:
            # write through .data: it does not bump the autograd version counter of the tensor saved for backward
            gate.data.fill_(g)
        self._last_gate = g
        return g

    def forward(self, out, y, is_peak, net):
        g = self._set_gate(net)
        profile_loss = mnll(out["profile"].float(), y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        aux_keys = [k for k in out if isinstance(k, str) and k.startswith("aux_")]
        aux_loss = torch.zeros((), device=profile_loss.device)
        for k in aux_keys:
            res = int(k[4:])
            logits = out[k].float()
            aux_loss = aux_loss + mnll(logits, self._binned(y, res, logits.shape[-1])).mean()
        if aux_keys:
            aux_loss = aux_loss / len(aux_keys)
        prof_term = profile_loss + self.AUX_WEIGHT * aux_loss
        loss = prof_term / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        return loss.sum(), {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach(),
                            "aux_mnll": aux_loss.detach(), "count_gate": torch.tensor(g)}

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5
BLOCKS_PER_STAGE = 2
DILATIONS = (1, 2, 4, 8)
RES_SCALE = 0.2


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block (used only at the start of the baseline bottleneck)."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class MatConv1d(nn.Module):
    """'Same' dense conv whose weight is stored as a 2-D (cout, cin*k) matrix, so Muon optimises it."""

    def __init__(self, cin, cout, k, dilation=1, bias=True):
        super().__init__()
        self.cin, self.cout, self.k, self.dilation = cin, cout, k, dilation
        self.weight = nn.Parameter(torch.empty(cout, cin * k))
        nn.init.normal_(self.weight, std=1.0 / math.sqrt(cin * k))
        self.bias = nn.Parameter(torch.zeros(cout)) if bias else None

    def forward(self, x):
        w = self.weight.view(self.cout, self.cin, self.k).to(x.dtype)
        b = self.bias.to(x.dtype) if self.bias is not None else None
        return F.conv1d(x, w, b, padding=self.dilation * (self.k - 1) // 2, dilation=self.dilation)


class DilatedResBlock(nn.Module):
    """Pre-activation residual block: GN, GELU, k=3 dilated conv, GN, GELU, k=1 conv, scaled residual add."""

    def __init__(self, channels, dilation, scale=RES_SCALE):
        super().__init__()
        self.norm1, self.norm2 = group_norm(channels), group_norm(channels)
        self.conv1 = MatConv1d(channels, channels, 3, dilation)
        self.conv2 = MatConv1d(channels, channels, 1)
        self.scale = scale

    def forward(self, x):
        y = self.conv1(F.gelu(self.norm1(x)))
        y = self.conv2(F.gelu(self.norm2(y)))
        return x + self.scale * y


def stage_blocks(width, stage):
    return nn.Sequential(*[DilatedResBlock(width, DILATIONS[(BLOCKS_PER_STAGE * stage + j) % len(DILATIONS)])
                           for j in range(BLOCKS_PER_STAGE)])


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.stages = nn.ModuleList([stage_blocks(width, s) for s in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for stage in self.stages:
            x = stage(x)
            skips.append(x)
            x = F.max_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class TransposedUp(nn.Module):
    """Transposed conv k=2, s=2 written as a per-position Linear(C, 2C) plus interleave (2-D weight for Muon)."""

    def __init__(self, width=WIDTH):
        super().__init__()
        self.lin = nn.Linear(width, 2 * width)

    def forward(self, x):
        b, c, l = x.shape
        y = self.lin(x.transpose(1, 2))
        return y.reshape(b, l, 2, c).reshape(b, 2 * l, c).transpose(1, 2)


class ConcatFusion(nn.Module):
    def __init__(self, width=WIDTH):
        super().__init__()
        self.proj = MatConv1d(2 * width, width, 1)

    def forward(self, up, skip):
        return self.proj(torch.cat([up, skip], 1))


class Decoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.up = nn.ModuleList([TransposedUp(width) for _ in range(n_stages)])
        self.fuse = nn.ModuleList([ConcatFusion(width) for _ in range(n_stages)])
        self.stages = nn.ModuleList([stage_blocks(width, s) for s in range(n_stages)])
        self.aux_heads = nn.ModuleList([nn.Conv1d(width, 1, 1) for _ in range(n_stages - 1)])
        for h in self.aux_heads:
            nn.init.zeros_(h.weight)
            nn.init.zeros_(h.bias)

    def forward(self, z, skips):
        x, aux = z, []
        for i, (up, fuse, stage, skip) in enumerate(zip(self.up, self.fuse, self.stages, reversed(skips))):
            u = up(x)[..., :skip.shape[-1]]
            x = stage(fuse(u, skip))
            if self.training and i < len(self.aux_heads):
                aux.append(self.aux_heads[i](x))
        return x, aux


class ProfileHead(nn.Module):
    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0

    def forward(self, x):
        in_len = x.shape[-1]
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        h, aux = self.decoder(z, skips)
        profile = self.profile_head(h)
        out = {"profile": profile, "counts": counts}
        if aux:
            start = (in_len - OUT_LEN) // 2
            aux_full = []
            for i, a in enumerate(aux):
                r = 2 ** (N_STAGES - 1 - i)
                aux_full.append(a.repeat_interleave(r, dim=-1)[..., start:start + OUT_LEN])
            out["aux_profiles"] = aux_full
        return out


def build_model():
    return CAPY()

# --- block: objective ---
DS_WEIGHT = 0.5


class Objective(nn.Module):
    """Cherimoya's Kendall-Gal weighted MNLL + count MSE, plus deep supervision: MNLL of the decoder's coarse-stage
    logits (16/8/4/2 bp, repeated to base resolution, which gives the same gradient as MNLL on binned counts),
    averaged over stages and added to the profile loss with weight DS_WEIGHT."""

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def forward(self, out, y, is_peak, net):
        profile_loss = mnll(out["profile"].float(), y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        logs = {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach()}
        profile_term = profile_loss
        aux = out.get("aux_profiles", None)
        if aux:
            ds = sum(mnll(a.float(), y).mean() for a in aux) / len(aux)
            profile_term = profile_term + DS_WEIGHT * ds
            logs["aux_mnll"] = ds.detach()
        loss = profile_term / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        return loss.sum(), logs

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
DEC_WIDTH = 192
N_STAGES = 5


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block (used only in the bottleneck here)."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    """CAPYBARA pre-activation conv block: norm -> GELU -> dropout -> conv."""

    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    """CAPYBARA HybridAttentionUnit: a residual pair of conv blocks, then pre-norm multi-head self-attention and an MLP."""

    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class SqueezeExcite(nn.Module):
    """Global average pool -> C/8 -> GELU -> C -> sigmoid, all statistics in float32."""

    def __init__(self, channels, reduction=8):
        super().__init__()
        hidden = max(16, channels // reduction)
        self.fc1 = nn.Linear(channels, hidden)
        self.fc2 = nn.Linear(hidden, channels)
        nn.init.zeros_(self.fc2.weight)
        nn.init.zeros_(self.fc2.bias)

    def forward(self, x):
        with torch.autocast(device_type=x.device.type, enabled=False):
            s = x.float().mean(-1)
            s = F.gelu(F.linear(s, self.fc1.weight.float(), self.fc1.bias.float()))
            s = 2.0 * torch.sigmoid(F.linear(s, self.fc2.weight.float(), self.fc2.bias.float()))
        return x * s.unsqueeze(-1).to(x.dtype)


class SEResBlock(nn.Module):
    """Pre-activation ResNet block: GN-GELU-conv5, GN-GELU-dropout-conv5, squeeze-excitation, scaled residual add."""

    def __init__(self, channels, k=5, dropout=0.1, init_scale=0.1):
        super().__init__()
        self.norm1, self.norm2 = group_norm(channels), group_norm(channels)
        self.conv1 = StandardizedConv1d(channels, channels, k)
        self.conv2 = StandardizedConv1d(channels, channels, k)
        self.drop = nn.Dropout(dropout)
        self.se = SqueezeExcite(channels)
        self.gamma = nn.Parameter(torch.full((channels, 1), init_scale))

    def forward(self, x):
        h = self.conv1(F.gelu(self.norm1(x)))
        h = self.conv2(self.drop(F.gelu(self.norm2(h))))
        h = self.se(h)
        return x + h * self.gamma.to(h.dtype)


class StridedDown(nn.Module):
    """Strided k=2 conv downsampling (right-pads odd lengths, like ceil-mode pooling)."""

    def __init__(self, channels):
        super().__init__()
        self.conv = nn.Conv1d(channels, channels, 2, stride=2)

    def forward(self, x):
        if x.shape[-1] % 2:
            x = F.pad(x, (0, 1))
        return self.conv(x)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([SEResBlock(width) for _ in range(n_stages)])
        self.downs = nn.ModuleList([StridedDown(width) for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block, down in zip(self.blocks, self.downs):
            x = block(x)
            skips.append(x)
            x = down(x)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    """CAPYBARA YCountHead (unchanged from the baseline)."""

    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class Decoder(nn.Module):
    """Narrow decoder: nearest upsample + k=3 conv, additive (1x1-projected) skips, one SE residual block per stage."""

    def __init__(self, enc_width=WIDTH, width=DEC_WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.inp = nn.Conv1d(enc_width, width, 1)
        self.up_convs = nn.ModuleList([StandardizedConv1d(width, width, 3) for _ in range(n_stages)])
        self.skip_proj = nn.ModuleList([nn.Conv1d(enc_width, width, 1) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([SEResBlock(width) for _ in range(n_stages)])
        self.out_norm = group_norm(width)

    def forward(self, z, skips):
        x = self.inp(z)
        for up, proj, block, skip in zip(self.up_convs, self.skip_proj, self.blocks, reversed(skips)):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = up(F.gelu(x)) + proj(skip)
            x = block(x)
        return F.gelu(self.out_norm(x))


class ProfileHead(nn.Module):
    """Nonlinear profile head: k=1 conv to 64, GELU, then a k=75 conv; central 1,000 positions."""

    def __init__(self, width=DEC_WIDTH, hidden=64, k=75):
        super().__init__()
        self.reduce = nn.Conv1d(width, hidden, 1)
        self.conv = nn.Conv1d(hidden, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(F.gelu(self.reduce(h)))[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        profile = self.profile_head(self.decoder(z, skips))
        return {"profile": profile, "counts": counts}


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's training loss (cherimoya.py fit + losses._mixture_loss): profile MNLL and count MSE on ln(total + 1),
    weighted by Kendall-Gal learned weights 1 / (2 s^2) with the regulariser (log s)^2. As in cherimoya, the weights stop
    learning after the first epoch in which the mean absolute gradient of s0 falls below 1."""

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def forward(self, out, y, is_peak, net):
        """`out` is the model's output dict, y (B, 1, 1000) raw targets, is_peak (B,) bool. Returns (loss, logs)."""
        profile_loss = mnll(out["profile"], y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        loss = profile_loss / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        return loss.sum(), {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach()}

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5
AUX_RES = (16, 8, 4, 2)


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block (used once at the bottleneck entry, as in the baseline)."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class InceptionBlock(nn.Module):
    """Pre-norm inception block: parallel depthwise k=3, k=9, k=19, dilated k=3 (d=4) convs and a stride-1 max-pool,
    concatenated (5C), GELU, linear 5C -> C, GELU, linear C -> C, added back with a per-channel layer scale (init 0.1)."""

    def __init__(self, channels, layer_scale=0.1):
        super().__init__()
        self.norm = group_norm(channels)
        self.dw = nn.ModuleList([
            nn.Conv1d(channels, channels, 3, padding=1, groups=channels),
            nn.Conv1d(channels, channels, 9, padding=4, groups=channels),
            nn.Conv1d(channels, channels, 19, padding=9, groups=channels),
            nn.Conv1d(channels, channels, 3, padding=4, dilation=4, groups=channels),
        ])
        self.proj1 = nn.Linear(5 * channels, channels)
        self.proj2 = nn.Linear(channels, channels)
        for lin in (self.proj1, self.proj2):
            nn.init.trunc_normal_(lin.weight, std=0.02)
            nn.init.zeros_(lin.bias)
        self.gamma = nn.Parameter(torch.full((channels,), float(layer_scale)))

    def forward(self, x):
        h = self.norm(x).to(x.dtype)
        branches = [conv(h) for conv in self.dw]
        branches.append(F.max_pool1d(h, 3, stride=1, padding=1))
        y = F.gelu(torch.cat(branches, 1), approximate="tanh").transpose(1, 2)
        y = self.proj2(F.gelu(self.proj1(y), approximate="tanh"))
        y = (y * self.gamma.to(y.dtype)).transpose(1, 2)
        return x + y


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([InceptionBlock(width) for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    """One inception block per stage after a gated skip fusion; returns the final features and every stage's output."""

    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([InceptionBlock(width) for _ in range(n_stages)])

    def forward(self, z, skips):
        x, stages = z, []
        for fuse, block, skip in zip(self.fuse, self.blocks, reversed(skips)):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = block(fuse(x, skip))
            stages.append(x)
        return x, stages


class ProfileHead(nn.Module):
    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.aux_heads = nn.ModuleList([nn.Conv1d(WIDTH, 1, 1) for _ in AUX_RES])
        for head in self.aux_heads:
            nn.init.zeros_(head.weight)
            nn.init.zeros_(head.bias)
        self.progress, self.epoch = 0.0, 0

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        h, stages = self.decoder(z, skips)
        profile = self.profile_head(h)
        out = {"profile": profile, "counts": counts}
        if self.training:
            start = (x.shape[-1] - OUT_LEN) // 2
            aux = []
            for head, s, r in zip(self.aux_heads, stages[:len(AUX_RES)], AUX_RES):
                a = head(s).float().repeat_interleave(r, dim=-1)
                aux.append(a[..., start:start + OUT_LEN])
            out["aux"] = aux
        return out


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's Kendall-Gal weighted profile MNLL + count MSE, plus deep supervision: the mean MNLL of the auxiliary
    decoder-stage profile heads (16, 8, 4, 2 bp, logits repeated to base resolution, which matches binned MNLL up to a
    constant), weight 0.5, added to the profile term."""

    def __init__(self, aux_weight=0.5):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))
        self.aux_weight = aux_weight

    def forward(self, out, y, is_peak, net):
        profile_loss = mnll(out["profile"], y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        aux = out.get("aux", None)
        profile_term = profile_loss
        logs = {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach()}
        if aux:
            aux_loss = sum(mnll(a, y).mean() for a in aux) / len(aux)
            profile_term = profile_term + self.aux_weight * aux_loss
            logs["aux_mnll"] = aux_loss.detach()
        loss = profile_term / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        return loss.sum(), logs

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5
GROWTH = 64
ENC_LAYERS = 4
DEC_LAYERS = 2


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block (used once in the bottleneck, as in the baseline)."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class DenseLayer(nn.Module):
    """DenseNet layer: GroupNorm (float32 under autocast) -> GELU -> k=5 conv to `growth` channels."""

    def __init__(self, cin, growth=GROWTH, k=5):
        super().__init__()
        self.norm = group_norm(cin)
        self.conv = nn.Conv1d(cin, growth, k, padding=k // 2)

    def forward(self, x):
        return self.conv(F.gelu(self.norm(x)))


class DenseStage(nn.Module):
    """n dense layers, each output concatenated onto the running input."""

    def __init__(self, cin, n_layers, growth=GROWTH):
        super().__init__()
        self.layers = nn.ModuleList([DenseLayer(cin + i * growth, growth) for i in range(n_layers)])
        self.out_channels = cin + n_layers * growth

    def forward(self, x):
        for layer in self.layers:
            x = torch.cat([x, layer(x).to(x.dtype)], 1)
        return x


class Transition(nn.Module):
    """GroupNorm -> GELU -> 1x1 projection (as nn.Linear so Muon trains it) back to `cout` channels."""

    def __init__(self, cin, cout=WIDTH):
        super().__init__()
        self.norm = group_norm(cin)
        self.proj = nn.Linear(cin, cout)

    def forward(self, x):
        y = F.gelu(self.norm(x)).transpose(1, 2)
        return self.proj(y).transpose(1, 2)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES, n_layers=ENC_LAYERS):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.dense = nn.ModuleList()
        self.trans = nn.ModuleList()
        for _ in range(n_stages):
            stage = DenseStage(width, n_layers)
            self.dense.append(stage)
            self.trans.append(Transition(stage.out_channels, width))

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for dense, trans in zip(self.dense, self.trans):
            x = trans(dense(x))
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class Decoder(nn.Module):
    """Per stage: nearest upsample, concatenate the encoder skip, DEC_LAYERS dense layers, transition back to WIDTH."""

    def __init__(self, width=WIDTH, n_stages=N_STAGES, n_layers=DEC_LAYERS):
        super().__init__()
        self.dense = nn.ModuleList()
        self.trans = nn.ModuleList()
        for _ in range(n_stages):
            stage = DenseStage(2 * width, n_layers)
            self.dense.append(stage)
            self.trans.append(Transition(stage.out_channels, width))

    def forward(self, z, skips):
        x = z
        for dense, trans, skip in zip(self.dense, self.trans, reversed(skips)):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = torch.cat([x, skip.to(x.dtype)], 1)
            x = trans(dense(x))
        return x


class ProfileHead(nn.Module):
    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        profile = self.profile_head(self.decoder(z, skips))
        return {"profile": profile, "counts": counts}


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's training loss (cherimoya.py fit + losses._mixture_loss): profile MNLL and count MSE on ln(total + 1),
    weighted by Kendall-Gal learned weights 1 / (2 s^2) with the regulariser (log s)^2. As in cherimoya, the weights stop
    learning after the first epoch in which the mean absolute gradient of s0 falls below 1."""

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def forward(self, out, y, is_peak, net):
        """`out` is the model's output dict, y (B, 1, 1000) raw targets, is_peak (B,) bool. Returns (loss, logs)."""
        profile_loss = mnll(out["profile"], y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        loss = profile_loss / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        return loss.sum(), {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach()}

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block: 3-tap dilated depthwise conv, per-example plane layer norm, MLP C->2C->C added with scale 0.15."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class OverlapAttentionPool1d(nn.Module):
    """Per-channel attention pooling over overlapping windows of 4, stride 2, output length ceil(L/2). Scores come from a
    zero-initialised kernel-1 conv (C->C); softmax and the weighted sum are computed in float32, padding is masked, so at
    init this is a 4-tap average over the valid positions."""

    def __init__(self, channels, k=4, stride=2):
        super().__init__()
        self.k, self.stride = k, stride
        self.score = nn.Conv1d(channels, channels, 1)
        nn.init.zeros_(self.score.weight)
        nn.init.zeros_(self.score.bias)

    def forward(self, x):
        length = x.shape[-1]
        n = (length + 1) // 2
        right = 2 * n + 1 - length
        s = self.score(x).float()
        xf = F.pad(x.float(), (1, right))
        s = F.pad(s, (1, right), value=-1e4)
        xw = xf.unfold(2, 4, 2)
        w = torch.softmax(s.unfold(2, 4, 2), dim=-1)
        return (xw * w).sum(-1).to(x.dtype)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([CheriBlock(width) for _ in range(n_stages)])
        self.pools = nn.ModuleList([OverlapAttentionPool1d(width) for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block, pool in zip(self.blocks, self.pools):
            x = block(x)
            skips.append(x)
            x = pool(x)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class MultiQueryAttentionPool(nn.Module):
    """Q learned queries, each a zero-initialised kernel-1 score over positions; float32 softmax over all positions;
    output (B, C*Q) in the same (C, Q) flatten order as adaptive pooling to Q bins."""

    def __init__(self, channels, queries=4):
        super().__init__()
        self.score = nn.Conv1d(channels, queries, 1)
        nn.init.zeros_(self.score.weight)
        nn.init.zeros_(self.score.bias)

    def forward(self, h):
        w = torch.softmax(self.score(h).float(), dim=-1)
        pooled = torch.einsum("bcl,bql->bcq", h.float(), w)
        return pooled.flatten(1).to(h.dtype)


class YCountHead(nn.Module):
    """YCountHead with conv [128, 64] (k5, GN, GELU, dropout, max-pool 2), then a 4-query attention pool instead of the
    adaptive average pool, MLP [64] with LayerNorm, one output ln(total + 1)."""

    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, queries=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs = nn.Sequential(*layers)
        self.pool = MultiQueryAttentionPool(c, queries)
        layers, d = [], c * queries
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(self.pool(self.convs(z)))


class GatedSkipFusion(nn.Module):
    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    """Gated-skip Cheri decoder; zero-initialised kernel-1 auxiliary profile heads on the 16, 8, 4 and 2 bp stages."""

    def __init__(self, width=WIDTH, n_stages=N_STAGES, blocks_per_stage=2):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[CheriBlock(width) for _ in range(blocks_per_stage)])
                                     for _ in range(n_stages)])
        self.aux_heads = nn.ModuleList([nn.Conv1d(width, 1, 1) for _ in range(n_stages - 1)])
        for head in self.aux_heads:
            nn.init.zeros_(head.weight)
            nn.init.zeros_(head.bias)

    def forward(self, z, skips):
        x, aux = z, []
        n = len(self.blocks)
        for i, (fuse, blocks, skip) in enumerate(zip(self.fuse, self.blocks, reversed(skips))):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = blocks(fuse(x, skip))
            if i < n - 1:
                aux.append(self.aux_heads[i](x))
        return x, aux


class ProfileHead(nn.Module):
    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        h, aux = self.decoder(z, skips)
        profile = self.profile_head(h)
        out = {"profile": profile, "counts": counts}
        if self.training:
            full = h.shape[-1]
            start = (full - OUT_LEN) // 2
            ups = [F.interpolate(a.float(), size=full, mode="nearest")[..., start:start + OUT_LEN] for a in aux]
            out["aux_profile"] = torch.cat(ups, 1)
        return out


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's Kendall-Gal weighted MNLL + count MSE, plus deep supervision: the decoder's auxiliary profile logits at
    16/8/4/2 bp (piecewise-constant, upsampled to 1 bp) are trained with MNLL against the raw targets, weight 0.5 in total
    (mean over the aux heads), added to the profile term."""

    def __init__(self, aux_weight=0.5):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))
        self.aux_weight = aux_weight

    def forward(self, out, y, is_peak, net):
        profile_loss = mnll(out["profile"].float(), y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        logs = {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach()}
        profile_term = profile_loss
        aux = out.get("aux_profile")
        if aux is not None:
            n = aux.shape[1]
            aux_loss = sum(mnll(aux[:, i:i + 1].float(), y).mean() for i in range(n)) / n
            profile_term = profile_term + self.aux_weight * aux_loss
            logs["aux_mnll"] = aux_loss.detach()
        loss = profile_term / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        return loss.sum(), logs

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5
IN_LEN = 2114


class CheriBlock(nn.Module):
    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([CheriBlock(width) for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    """Returns the base-resolution features and the outputs of every stage (coarsest first)."""

    def __init__(self, width=WIDTH, n_stages=N_STAGES, blocks_per_stage=2):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[CheriBlock(width) for _ in range(blocks_per_stage)])
                                     for _ in range(n_stages)])

    def forward(self, z, skips):
        x, stages = z, []
        for fuse, blocks, skip in zip(self.fuse, self.blocks, reversed(skips)):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = blocks(fuse(x, skip))
            stages.append(x)
        return x, stages


class ProfileHead(nn.Module):
    """Cherimoya's profile head (kernel-75 conv, central 1,000 positions) plus zero-initialised kernel-1 deep-supervision
    heads on the decoder stages at 16, 8, 4 and 2 bp, cropped to the bins that cover the central 1,000 bp."""

    def __init__(self, width=WIDTH, k=75, aux_res=(16, 8, 4, 2)):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)
        self.aux_res = aux_res
        self.aux = nn.ModuleList([nn.Conv1d(width, 1, 1) for _ in aux_res])
        for m in self.aux:
            nn.init.zeros_(m.weight)
            nn.init.zeros_(m.bias)

    def forward(self, h, stages=None):
        start = (h.shape[-1] - OUT_LEN) // 2
        logits = self.conv(h)[..., start:start + OUT_LEN]
        aux = []
        if stages is not None:
            s0, s1 = (IN_LEN - OUT_LEN) // 2, (IN_LEN - OUT_LEN) // 2 + OUT_LEN
            for head, r, feat in zip(self.aux, self.aux_res, stages):
                b0, b1 = s0 // r, -(-s1 // r)
                aux.append(head(feat[..., b0:b1]))
        return logits, aux


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        h, stages = self.decoder(z, skips)
        profile, aux = self.profile_head(h, stages[:4] if self.training else None)
        out = {"profile": profile, "counts": counts}
        if self.training:
            out["aux_profile"] = aux
        return out


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's Kendall-Gal mixture loss plus decoder deep supervision: MNLL of each auxiliary decoder-stage head (16, 8,
    4, 2 bp) against the counts summed into exactly aligned bins over the central 1,000 bp, weight 0.5 each."""

    AUX_RES = (16, 8, 4, 2)
    AUX_WEIGHT = 0.5
    IN_LEN, OUT_LEN = 2114, 1000

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def _binned(self, y, r):
        s0 = (self.IN_LEN - self.OUT_LEN) // 2
        s1 = s0 + self.OUT_LEN
        b0, b1 = s0 // r, -(-s1 // r)
        yp = torch.nn.functional.pad(y, (s0 - b0 * r, b1 * r - s1))
        return yp.reshape(y.shape[0], y.shape[1], b1 - b0, r).sum(-1)

    def forward(self, out, y, is_peak, net):
        profile_loss = mnll(out["profile"], y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        aux_loss = torch.zeros((), device=y.device)
        for logits, r in zip(out.get("aux_profile", []), self.AUX_RES):
            aux_loss = aux_loss + mnll(logits.float(), self._binned(y, r)).mean()
        loss = (profile_loss + self.AUX_WEIGHT * aux_loss) / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        return loss.sum(), {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach(),
                            "aux_mnll": aux_loss.detach()}

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

