class CAPY(nn.Module):
    """Baseline CAPY with a late count-trunk detach: the count head reads z.detach() + g*(z - z.detach()); g goes 1 -> 0
    linearly between 72% and 82% of training. g lives in a buffer set by the progress setter (no recompiles)."""

    def __init__(self):
        super().__init__()
        self.register_buffer("count_gate", torch.ones(()), persistent=False)
        self._progress = 0.0
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0

    @property
    def progress(self):
        return self._progress

    @progress.setter
    def progress(self, p):
        self._progress = float(p)
        g = min(1.0, max(0.0, 1.0 - (float(p) - DETACH_START) / DETACH_RAMP))
        if "count_gate" in self._buffers:
            self._buffers["count_gate"].fill_(g)

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        zd = z.detach()
        counts = self.count_head(zd + self.count_gate.to(z.dtype) * (z - zd))
        profile = self.profile_head(self.decoder(z, skips))
        return {"profile": profile, "counts": counts}


