class StandardizedConv1d(nn.Conv1d):
    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([CheriBlock(width) for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=4):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES, blocks_per_stage=2):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[CheriBlock(width) for _ in range(blocks_per_stage)])
                                     for _ in range(n_stages)])

    def forward(self, z, skips):
        x = z
        for fuse, blocks, skip in zip(self.fuse, self.blocks, reversed(skips)):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = blocks(fuse(x, skip))
        return x


class ProfileHead(nn.Module):
    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        profile = self.profile_head(self.decoder(z, skips))
        return {"profile": profile, "counts": counts}


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's training loss (cherimoya.py fit + losses._mixture_loss): profile MNLL and count MSE on ln(total + 1),
    weighted by Kendall-Gal learned weights 1 / (2 s^2) with the regulariser (log s)^2. As in cherimoya, the weights stop
    learning after the first epoch in which the mean absolute gradient of s0 falls below 1."""

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def forward(self, out, y, is_peak, net):
        """`out` is the model's output dict, y (B, 1, 1000) raw targets, is_peak (B,) bool. Returns (loss, logs)."""
        profile_loss = mnll(out["profile"], y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        loss = profile_loss / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        return loss.sum(), {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach()}

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5
DILATIONS = (1, 2, 4, 8)


class ConvNeXtBlock(nn.Module):
    """ConvNeXt block: k=7 dilated depthwise conv, per-position channel LayerNorm (float32), MLP C -> 4C -> C (tanh GELU),
    layer scale initialised at 1e-2, residual add."""

    def __init__(self, channels, dilation=1, k=7, expansion=4, layer_scale=1e-2, eps=1e-6):
        super().__init__()
        self.channels, self.eps = channels, eps
        self.dw = nn.Conv1d(channels, channels, k, padding=dilation * (k // 2), dilation=dilation, groups=channels)
        self.norm_weight = nn.Parameter(torch.ones(channels))
        self.norm_bias = nn.Parameter(torch.zeros(channels))
        self.linear1 = nn.Linear(channels, expansion * channels)
        self.linear2 = nn.Linear(expansion * channels, channels)
        self.activation = nn.GELU(approximate="tanh")
        self.gamma = nn.Parameter(torch.full((channels,), layer_scale))
        for w in (self.dw.weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)
        for b in (self.dw.bias, self.linear1.bias, self.linear2.bias):
            nn.init.zeros_(b)

    def forward(self, x):                      # x: (B, C, L)
        y = self.dw(x).transpose(1, 2)
        y = F.layer_norm(y.float(), (self.channels,), self.norm_weight.float(), self.norm_bias.float(), self.eps).to(x.dtype)
        y = self.linear2(self.activation(self.linear1(y)))
        y = y * self.gamma.to(y.dtype)
        return x + y.transpose(1, 2)


def stage_blocks(width, stage, per_stage=2):
    return nn.Sequential(*[ConvNeXtBlock(width, dilation=DILATIONS[(stage * per_stage + j) % len(DILATIONS)])
                           for j in range(per_stage)])


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    """CAPYBARA pre-activation conv block: norm -> GELU -> dropout -> conv."""

    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    """CAPYBARA HybridAttentionUnit: a residual pair of conv blocks, then pre-norm multi-head self-attention and an MLP."""

    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([stage_blocks(width, s) for s in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.entry = ConvNeXtBlock(width, dilation=1)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.entry(x))


class YCountHead(nn.Module):
    """CAPYBARA YCountHead: conv [128, 64] (kernel 5, GroupNorm, GELU, dropout, max-pool 2), adaptive average pool to 4
    bins, MLP [64] with LayerNorm, then one output: ln(total counts + 1)."""

    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    """up + 2*sigmoid(W[up; skip])*skip, W a zero-initialised kernel-1 conv, so the gate starts at 1."""

    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    """Gated-add skips, nearest upsampling, two ConvNeXt blocks per stage. Zero-initialised kernel-1 auxiliary profile
    heads on the 16, 8, 4 and 2 bp stage outputs (training only) for deep supervision."""

    def __init__(self, width=WIDTH, n_stages=N_STAGES, blocks_per_stage=2):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([stage_blocks(width, s, blocks_per_stage) for s in range(n_stages)])
        self.aux_heads = nn.ModuleList([nn.Conv1d(width, 1, 1) for _ in range(n_stages - 1)])
        for h in self.aux_heads:
            nn.init.zeros_(h.weight)
            nn.init.zeros_(h.bias)

    def forward(self, z, skips):
        x = z
        aux = []
        n = len(self.blocks)
        for i, (fuse, blocks, skip) in enumerate(zip(self.fuse, self.blocks, reversed(skips))):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = blocks(fuse(x, skip))
            if self.training and i < n - 1:
                aux.append(self.aux_heads[i](x))
        return x, aux


class ProfileHead(nn.Module):
    """Cherimoya's profile head: one kernel-75 conv, then the central 1,000 positions."""

    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        h, aux_raw = self.decoder(z, skips)
        profile = self.profile_head(h)
        out = {"profile": profile, "counts": counts}
        if len(aux_raw) > 0:
            full = h.shape[-1]
            start = (full - OUT_LEN) // 2
            # repeat coarse logits to base resolution (same nearest map as the decoder), crop the centre: MNLL on these
            # piecewise-constant logits equals binned MNLL up to a constant, without bin-alignment bookkeeping
            aux = [F.interpolate(a, size=full, mode="nearest")[..., start:start + OUT_LEN] for a in aux_raw]
            out["aux_profile"] = torch.cat(aux, 1)
        return out


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's Kendall-Gal weighted profile MNLL + count MSE, plus deep supervision: MNLL of the auxiliary decoder
    logits (16, 8, 4, 2 bp, repeated to base resolution), mean over stages, weight 0.5 relative to the main profile loss
    (scaled by the detached profile weight so the learned weights see only the main losses)."""

    def __init__(self, aux_weight=0.5):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))
        self.aux_weight = aux_weight

    def forward(self, out, y, is_peak, net):
        profile_loss = mnll(out["profile"], y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        w0 = 1.0 / (2 * self.s0 ** 2)
        w1 = 1.0 / (2 * self.s1 ** 2)
        loss = profile_loss * w0 + count_loss * w1
        logs = {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach()}
        if "aux_profile" in out:
            a = out["aux_profile"].float()
            n = a.shape[1]
            aux_loss = sum(mnll(a[:, i:i + 1], y).mean() for i in range(n)) / n
            loss = loss + self.aux_weight * aux_loss * w0.detach()
            logs["aux_mnll"] = aux_loss.detach()
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        return loss.sum(), logs

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5
PAD = 15  # 2114 + 2*15 = 2144 = 67 * 32: every pooling stage sees an even length, so pooling commutes with the RC


def rc(x):
    """Reverse complement of a (B, C, L) feature map: reverse channel order and length (one-hot ACGT -> TGCA)."""
    return x.flip(1, 2)


class RCLinear(nn.Module):
    """Pointwise linear on (..., C) with W[o, i] = W[O-1-o, I-1-i] (RCPS tying); only half the rows are parameters."""

    def __init__(self, cin, cout, bias=False, std=0.02):
        super().__init__()
        self.weight = nn.Parameter(torch.empty(cout // 2, cin))
        nn.init.trunc_normal_(self.weight, std=std)
        self.bias = nn.Parameter(torch.zeros(cout // 2)) if bias else None

    def forward(self, x):
        w = torch.cat([self.weight, self.weight.flip(0, 1)], 0)
        b = None if self.bias is None else torch.cat([self.bias, self.bias.flip(0)])
        return F.linear(x, w, b)


class RCConv1d(nn.Module):
    """'Same' conv (odd k) with W[o, i, k] = W[O-1-o, I-1-i, K-1-k]; optional CAPYBARA weight standardisation."""

    def __init__(self, cin, cout, k, dilation=1, bias=True, standardize=False, std=0.02, zero=False):
        super().__init__()
        self.k, self.dilation, self.fan_in = k, dilation, cin * k
        self.weight = nn.Parameter(torch.empty(cout // 2, cin, k))
        if zero:
            nn.init.zeros_(self.weight)
        else:
            nn.init.trunc_normal_(self.weight, std=std)
        self.bias = nn.Parameter(torch.zeros(cout // 2)) if bias else None
        self.scale = nn.Parameter(torch.ones(cout // 2, 1, 1)) if standardize else None

    def forward(self, x):
        w = self.weight
        if self.scale is not None:
            var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
            w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * self.fan_in, min=1e-4)) * self.scale
        w = torch.cat([w, w.flip(0, 1, 2)], 0)
        b = None if self.bias is None else torch.cat([self.bias, self.bias.flip(0)]).to(x.dtype)
        pad = self.dilation * (self.k - 1) // 2
        return F.conv1d(x, w.to(x.dtype), b, padding=pad, dilation=self.dilation)


class RCGroupNorm(nn.Module):
    """GroupNorm over contiguous channel groups (mirror-symmetric) with mirrored affine parameters, float32 statistics."""

    def __init__(self, channels, groups=8):
        super().__init__()
        while channels % groups:
            groups -= 1
        self.groups = groups
        self.weight = nn.Parameter(torch.ones(channels // 2))
        self.bias = nn.Parameter(torch.zeros(channels // 2))

    def forward(self, x):
        w = torch.cat([self.weight, self.weight.flip(0)])
        b = torch.cat([self.bias, self.bias.flip(0)])
        return F.group_norm(x.float(), self.groups, w.float(), b.float(), 1e-5).to(x.dtype)


class RCCheriBlock(nn.Module):
    """Cheri block with RC tying: mirrored depthwise taps on the paired channel half, plane norm, tied MLP."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels // 2))
        nn.init.trunc_normal_(self.conv_weight, std=0.02)
        self.linear1 = RCLinear(channels, expansion * channels)
        self.linear2 = RCLinear(expansion * channels, channels)
        self.activation = nn.GELU(approximate="tanh")

    def forward(self, x):
        c = x.shape[1]
        taps = torch.cat([self.conv_weight, self.conv_weight.flip(0, 1)], 1)       # (3, C)
        y = F.conv1d(x, taps.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class RCConvBlock(nn.Module):
    """Pre-activation conv block: tied norm -> GELU -> dropout -> tied standardised conv."""

    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = RCGroupNorm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = RCConv1d(channels, channels, k, standardize=True)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class RCAttention(nn.Module):
    """Multi-head self-attention with tied projections; contiguous heads map to mirrored heads under the RC."""

    def __init__(self, channels, heads=4, dropout=0.1):
        super().__init__()
        self.heads, self.p = heads, dropout
        self.q, self.k, self.v = (RCLinear(channels, channels, bias=True) for _ in range(3))
        self.o = RCLinear(channels, channels, bias=True)

    def forward(self, y):                      # y: (B, L, C)
        b, l, c = y.shape

        def split(t):
            return t.reshape(b, l, self.heads, c // self.heads).transpose(1, 2)

        a = F.scaled_dot_product_attention(split(self.q(y)), split(self.k(y)), split(self.v(y)),
                                           dropout_p=self.p if self.training else 0.0)
        return self.o(a.transpose(1, 2).reshape(b, l, c))


class RCHybridAttentionUnit(nn.Module):
    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = RCConvBlock(channels, k, dropout), RCConvBlock(channels, k, dropout)
        self.attn_norm = RCGroupNorm(channels)
        self.attn = RCAttention(channels, heads, attn_dropout)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = RCGroupNorm(channels)
        self.ffn = nn.Sequential(RCLinear(channels, hidden, bias=True), nn.GELU(), nn.Dropout(dropout),
                                 RCLinear(hidden, channels, bias=True), nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y).transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = RCConv1d(4, width, 21, std=0.02)
        self.blocks = nn.ModuleList([RCCheriBlock(width) for _ in range(n_stages)])

    def forward(self, x):
        x = F.pad(x, (PAD, PAD))                               # N columns; 2144 bp
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2)                             # even lengths: RC-equivariant
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = RCCheriBlock(width)
        self.units = nn.Sequential(*[RCHybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class RCInvariantCountHead(nn.Module):
    """Tied conv [128, 64] (k 5, tied GN, GELU, dropout), adaptive avg pool to 4 bins (mirror-symmetric on 67 positions),
    then an RC-invariant readout: bins + RC(bins), flattened into an MLP [64] with LayerNorm -> ln(total + 1)."""

    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [RCConv1d(c, h, k, bias=False, standardize=False, std=0.02), RCGroupNorm(h), nn.GELU(),
                       nn.Dropout(dropout)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        h = F.adaptive_avg_pool1d(self.convs(z), self.bins)
        h = h + rc(h)
        return self.mlp(h.flatten(1))


class RCGatedSkipFusion(nn.Module):
    """up + 2*sigmoid(Wu up + Ws skip)*skip with tied zero-initialised kernel-1 convs (gate starts at 1)."""

    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate_up = RCConv1d(width, width, 1, bias=True, zero=True)
        self.gate_skip = RCConv1d(width, width, 1, bias=False, zero=True)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate_up(up) + self.gate_skip(skip)) * skip


class Decoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES, blocks_per_stage=2):
        super().__init__()
        self.fuse = nn.ModuleList([RCGatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[RCCheriBlock(width) for _ in range(blocks_per_stage)])
                                     for _ in range(n_stages)])

    def forward(self, z, skips):
        x = z
        for fuse, blocks, skip in zip(self.fuse, self.blocks, reversed(skips)):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")   # exact 2x: RC-equivariant
            x = blocks(fuse(x, skip))
        return x


class ProfileHead(nn.Module):
    """Symmetric kernel-75 conv (W[i, k] = W[C-1-i, 74-k]) so the unstranded profile flips under the RC; central 1,000."""

    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.k = k
        self.weight = nn.Parameter(torch.empty(1, width, k))
        nn.init.trunc_normal_(self.weight, std=0.02)
        self.bias = nn.Parameter(torch.zeros(1))

    def forward(self, h):
        w = 0.5 * (self.weight + self.weight.flip(1, 2))
        out = F.conv1d(h, w.to(h.dtype), self.bias.to(h.dtype), padding=self.k // 2)
        start = (out.shape[-1] - OUT_LEN) // 2
        return out[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = RCInvariantCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        profile = self.profile_head(self.decoder(z, skips))
        return {"profile": profile, "counts": counts}


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's training loss (cherimoya.py fit + losses._mixture_loss): profile MNLL and count MSE on ln(total + 1),
    weighted by Kendall-Gal learned weights 1 / (2 s^2) with the regulariser (log s)^2. As in cherimoya, the weights stop
    learning after the first epoch in which the mean absolute gradient of s0 falls below 1."""

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def forward(self, out, y, is_peak, net):
        """`out` is the model's output dict, y (B, 1, 1000) raw targets, is_peak (B,) bool. Returns (loss, logs)."""
        profile_loss = mnll(out["profile"], y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        loss = profile_loss / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        return loss.sum(), {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach()}

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5
STAGE_WIDTHS = (128, 256, 256, 256, 256)
ENC_DILATIONS = ((1, 2, 4, 8, 16, 32), (1, 2, 4), (1, 2, 4), (1, 2, 4), (1, 2, 4))
DEC_DILATIONS = (1, 2)


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block (kept for the bottleneck entry)."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    """CAPYBARA pre-activation conv block: norm -> GELU -> dropout -> conv."""

    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    """CAPYBARA HybridAttentionUnit: a residual pair of conv blocks, then pre-norm multi-head self-attention and an MLP."""

    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class WaveNetBlock(nn.Module):
    """Pre-norm WaveNet gated residual block: GN -> k=3 dilated conv to 2C -> tanh(a)*sigmoid(b) in float32 -> dropout ->
    1x1 conv, added to the residual with a learnable per-channel scale (init 0.1)."""

    def __init__(self, channels, dilation, dropout=0.1, init_scale=0.1):
        super().__init__()
        self.norm = group_norm(channels)
        self.conv = nn.Conv1d(channels, 2 * channels, 3, padding=dilation, dilation=dilation)
        self.drop = nn.Dropout(dropout)
        self.out = nn.Conv1d(channels, channels, 1)
        self.gamma = nn.Parameter(torch.full((1, channels, 1), init_scale))

    def forward(self, x):
        h = self.conv(self.norm(x))
        a, b = h.float().chunk(2, dim=1)
        g = (torch.tanh(a) * torch.sigmoid(b)).to(h.dtype)
        y = self.out(self.drop(g))
        return x + self.gamma.to(y.dtype) * y


class Encoder(nn.Module):
    def __init__(self, widths=STAGE_WIDTHS, dilations=ENC_DILATIONS, out_width=WIDTH):
        super().__init__()
        self.stem = nn.Conv1d(4, widths[0], 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.stages = nn.ModuleList([nn.Sequential(*[WaveNetBlock(w, d) for d in dils])
                                     for w, dils in zip(widths, dilations)])
        nxt = list(widths[1:]) + [out_width]
        self.transitions = nn.ModuleList([nn.Conv1d(w, n, 1) if w != n else nn.Identity() for w, n in zip(widths, nxt)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for stage, trans in zip(self.stages, self.transitions):
            x = stage(x)
            skips.append(x)
            x = trans(F.max_pool1d(x, 2, ceil_mode=True))
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    """CAPYBARA YCountHead: conv [128, 64] (kernel 5, GroupNorm, GELU, dropout, max-pool 2), adaptive average pool to 4
    bins, MLP [64] with LayerNorm, then one output: ln(total counts + 1)."""

    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    """up + 2*sigmoid(W[up; skip])*skip, W a zero-initialised kernel-1 conv, so the gate starts at 1."""

    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    """Deepest stage first: transposed conv (k=2, s=2) up, crop to the skip length, gated-add skip, WaveNet blocks."""

    def __init__(self, widths=STAGE_WIDTHS, in_width=WIDTH, dilations=DEC_DILATIONS):
        super().__init__()
        ups, fuses, blocks = [], [], []
        cin = in_width
        for w in reversed(widths):
            ups.append(nn.ConvTranspose1d(cin, w, 2, stride=2))
            fuses.append(GatedSkipFusion(w))
            blocks.append(nn.Sequential(*[WaveNetBlock(w, d) for d in dilations]))
            cin = w
        self.ups, self.fuse, self.blocks = nn.ModuleList(ups), nn.ModuleList(fuses), nn.ModuleList(blocks)

    def forward(self, z, skips):
        x = z
        for up, fuse, blocks, skip in zip(self.ups, self.fuse, self.blocks, reversed(skips)):
            x = up(x)[..., :skip.shape[-1]]
            x = blocks(fuse(x, skip))
        return x


class ProfileHead(nn.Module):
    """Nonlinear bottleneck head: k=1 conv to 64, GELU, then the kernel-75 conv; central 1,000 positions."""

    def __init__(self, width=STAGE_WIDTHS[0], hidden=64, k=75):
        super().__init__()
        self.proj = nn.Conv1d(width, hidden, 1)
        self.conv = nn.Conv1d(hidden, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(F.gelu(self.proj(h)))[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        profile = self.profile_head(self.decoder(z, skips))
        return {"profile": profile, "counts": counts}


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's training loss (cherimoya.py fit + losses._mixture_loss): profile MNLL and count MSE on ln(total + 1),
    weighted by Kendall-Gal learned weights 1 / (2 s^2) with the regulariser (log s)^2. As in cherimoya, the weights stop
    learning after the first epoch in which the mean absolute gradient of s0 falls below 1."""

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def forward(self, out, y, is_peak, net):
        """`out` is the model's output dict, y (B, 1, 1000) raw targets, is_peak (B,) bool. Returns (loss, logs)."""
        profile_loss = mnll(out["profile"], y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        loss = profile_loss / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        return loss.sum(), {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach()}

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block (kept for the baseline bottleneck)."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


class SKBlock(nn.Module):
    """Selective-kernel block: depthwise branches k=3, k=11, k=5 (dilation 4); their sum is averaged over length (float32),
    an MLP gives per-channel softmax weights over the branches (float32, zero-init so they start equal); the branches are
    mixed by those weights, plane-normalised in float32, passed through a pointwise MLP and added back with a residual scale."""

    def __init__(self, channels, specs=((3, 1), (11, 1), (5, 4)), reduction=8, min_hidden=32, expansion=2,
                 residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.specs, self.residual_scale, self.eps = specs, residual_scale, eps
        self.branch_weights = nn.ParameterList([nn.Parameter(torch.empty(k, channels)) for k, _ in specs])
        for w in self.branch_weights:
            nn.init.trunc_normal_(w, std=0.02)
        hidden = max(channels // reduction, min_hidden)
        self.fc1 = nn.Linear(channels, hidden)
        self.fc2 = nn.Linear(hidden, len(specs) * channels)
        nn.init.zeros_(self.fc2.weight)
        nn.init.zeros_(self.fc2.bias)
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        nn.init.trunc_normal_(self.linear1.weight, std=0.02)
        nn.init.trunc_normal_(self.linear2.weight, std=0.02)
        self.activation = nn.GELU(approximate="tanh")

    def forward(self, x):                      # x: (B, C, L)
        b, c, _ = x.shape
        branches = []
        for w, (k, d) in zip(self.branch_weights, self.specs):
            branches.append(F.conv1d(x, w.t().unsqueeze(1).to(x.dtype), padding=d * (k - 1) // 2, dilation=d, groups=c))
        u = torch.stack(branches, 1)           # (B, M, C, L)
        s = u.float().sum(1).mean(-1)          # (B, C) float32 global descriptor
        s = s - s.mean(1, keepdim=True)
        s = s * (s.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt()
        logits = self.fc2(self.activation(self.fc1(s.to(x.dtype)))).float().view(b, len(self.specs), c)
        att = torch.softmax(logits, dim=1).to(x.dtype).unsqueeze(-1)
        v = (u * att).sum(1)                   # (B, C, L)
        flat = v.reshape(b, -1).float()
        v = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        v = v.reshape(x.shape).to(x.dtype).transpose(1, 2)
        v = self.linear2(self.activation(self.linear1(v))).transpose(1, 2)
        return x + v * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    """CAPYBARA pre-activation conv block: norm -> GELU -> dropout -> conv."""

    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    """CAPYBARA HybridAttentionUnit: a residual pair of conv blocks, then pre-norm multi-head self-attention and an MLP."""

    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([SKBlock(width) for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    """CAPYBARA YCountHead: conv [128, 64] (kernel 5, GroupNorm, GELU, dropout, max-pool 2), adaptive average pool to 4
    bins, MLP [64] with LayerNorm, then one output: ln(total counts + 1)."""

    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class ConcatSkipFusion(nn.Module):
    """1x1 conv over [up; skip], initialised to up + skip."""

    def __init__(self, width=WIDTH):
        super().__init__()
        self.proj = nn.Conv1d(2 * width, width, 1)
        with torch.no_grad():
            eye = torch.eye(width)
            self.proj.weight.copy_(torch.cat([eye, eye], 1).unsqueeze(-1))
            self.proj.bias.zero_()

    def forward(self, up, skip):
        return self.proj(torch.cat([up, skip], 1))


class Decoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES, blocks_per_stage=2):
        super().__init__()
        self.fuse = nn.ModuleList([ConcatSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[SKBlock(width) for _ in range(blocks_per_stage)])
                                     for _ in range(n_stages)])

    def forward(self, z, skips):
        x = z
        for fuse, blocks, skip in zip(self.fuse, self.blocks, reversed(skips)):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = blocks(fuse(x, skip))
        return x


class ProfileHead(nn.Module):
    """Cherimoya's profile head: one kernel-75 conv, then the central 1,000 positions."""

    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        profile = self.profile_head(self.decoder(z, skips))
        return {"profile": profile, "counts": counts}


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's training loss (cherimoya.py fit + losses._mixture_loss): profile MNLL and count MSE on ln(total + 1),
    weighted by Kendall-Gal learned weights 1 / (2 s^2) with the regulariser (log s)^2. As in cherimoya, the weights stop
    learning after the first epoch in which the mean absolute gradient of s0 falls below 1."""

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def forward(self, out, y, is_peak, net):
        """`out` is the model's output dict, y (B, 1, 1000) raw targets, is_peak (B,) bool. Returns (loss, logs)."""
        profile_loss = mnll(out["profile"], y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        loss = profile_loss / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        return loss.sum(), {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach()}

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
DEC_WIDTH = 320
N_STAGES = 5
ENC_BLOCKS = 2
DEC_BLOCKS = 2
AUX_RES = (16, 8, 4, 2)


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block (used only at the bottleneck entry, as in the baseline)."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Matrix1x1(nn.Module):
    """Kernel-1 conv whose weight is a 2-D matrix (cout, cin), so Muon trains it."""

    def __init__(self, cin, cout, bias=True):
        super().__init__()
        self.weight = nn.Parameter(torch.empty(cout, cin))
        nn.init.trunc_normal_(self.weight, std=cin ** -0.5)
        self.bias = nn.Parameter(torch.zeros(cout)) if bias else None

    def forward(self, x):
        b = None if self.bias is None else self.bias.to(x.dtype)
        return F.conv1d(x, self.weight.unsqueeze(-1).to(x.dtype), b)


class MatrixConv1d(nn.Module):
    """k-tap 'same' conv with weight stored 2-D (cout, cin*k) so Muon trains it."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__()
        self.cin, self.cout, self.k, self.dilation = cin, cout, k, dilation
        self.weight = nn.Parameter(torch.empty(cout, cin * k))
        nn.init.trunc_normal_(self.weight, std=(cin * k) ** -0.5)
        self.bias = nn.Parameter(torch.zeros(cout))

    def forward(self, x):
        w = self.weight.view(self.cout, self.cin, self.k).to(x.dtype)
        total = self.dilation * (self.k - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w, self.bias.to(x.dtype), dilation=self.dilation)


class Res2NetBlock(nn.Module):
    """1x1 conv -> GN -> GELU, split into 4 groups; group i: k=5 conv of (x_i + y_{i-1}) -> GN -> GELU (hierarchical
    receptive field 5/9/13/17 bp); concat -> dropout -> 1x1 conv -> GN -> GELU, residual add with layer scale."""

    def __init__(self, channels, scales=4, k=5, dropout=0.1, layer_scale=0.1):
        super().__init__()
        g = channels // scales
        self.scales = scales
        self.inp = Matrix1x1(channels, channels)
        self.inp_norm = group_norm(channels)
        self.convs = nn.ModuleList([MatrixConv1d(g, g, k) for _ in range(scales)])
        self.norms = nn.ModuleList([group_norm(g) for _ in range(scales)])
        self.drop = nn.Dropout(dropout)
        self.out = Matrix1x1(channels, channels)
        self.out_norm = group_norm(channels)
        self.gamma = nn.Parameter(torch.full((1, channels, 1), layer_scale))

    def forward(self, x):
        h = F.gelu(self.inp_norm(self.inp(x)))
        parts = torch.chunk(h, self.scales, 1)
        outs, prev = [], None
        for p, conv, norm in zip(parts, self.convs, self.norms):
            if prev is not None:
                p = p + prev
            prev = F.gelu(norm(conv(p)))
            outs.append(prev)
        h = torch.cat(outs, 1)
        h = F.gelu(self.out_norm(self.out(self.drop(h))))
        return x + self.gamma * h


class StridedDown(nn.Module):
    """Strided k=2 conv (weight 2-D for Muon); odd lengths are zero-padded on the right (ceil length)."""

    def __init__(self, channels):
        super().__init__()
        self.c = channels
        self.weight = nn.Parameter(torch.empty(channels, channels * 2))
        nn.init.trunc_normal_(self.weight, std=(2 * channels) ** -0.5)
        self.bias = nn.Parameter(torch.zeros(channels))

    def forward(self, x):
        if x.shape[-1] % 2:
            x = F.pad(x, (0, 1))
        w = self.weight.view(self.c, self.c, 2).to(x.dtype)
        return F.conv1d(x, w, self.bias.to(x.dtype), stride=2)


class TransposedUp(nn.Module):
    """Transposed conv k=2, stride 2 (weight 2-D for Muon), cropped on the right to the skip's length."""

    def __init__(self, cin, cout):
        super().__init__()
        self.cin, self.cout = cin, cout
        self.weight = nn.Parameter(torch.empty(cin, cout * 2))
        nn.init.trunc_normal_(self.weight, std=cin ** -0.5)
        self.bias = nn.Parameter(torch.zeros(cout))

    def forward(self, x, length):
        w = self.weight.view(self.cin, self.cout, 2).to(x.dtype)
        return F.conv_transpose1d(x, w, self.bias.to(x.dtype), stride=2)[..., :length]


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES, blocks_per_stage=ENC_BLOCKS):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([nn.Sequential(*[Res2NetBlock(width) for _ in range(blocks_per_stage)])
                                     for _ in range(n_stages)])
        self.downs = nn.ModuleList([StridedDown(width) for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for blocks, down in zip(self.blocks, self.downs):
            x = blocks(x)
            skips.append(x)
            x = down(x)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class Decoder(nn.Module):
    """Transposed-conv upsampling, additive skips (1x1 projection 256 -> 320), Res2Net blocks at 320 channels.
    Returns the output of every stage (16, 8, 4, 2, 1 bp)."""

    def __init__(self, enc_width=WIDTH, width=DEC_WIDTH, n_stages=N_STAGES, blocks_per_stage=DEC_BLOCKS):
        super().__init__()
        self.ups = nn.ModuleList([TransposedUp(enc_width if i == 0 else width, width) for i in range(n_stages)])
        self.skip_proj = nn.ModuleList([Matrix1x1(enc_width, width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[Res2NetBlock(width) for _ in range(blocks_per_stage)])
                                     for _ in range(n_stages)])

    def forward(self, z, skips):
        x, outs = z, []
        for up, proj, blocks, skip in zip(self.ups, self.skip_proj, self.blocks, reversed(skips)):
            x = up(x, skip.shape[-1]) + proj(skip)
            x = blocks(x)
            outs.append(x)
        return outs


class ProfileHead(nn.Module):
    """One kernel-75 conv on the 320-channel decoder output, then the central 1,000 positions."""

    def __init__(self, width=DEC_WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class AuxProfileHeads(nn.Module):
    """Zero-initialised kernel-1 deep-supervision heads at 16, 8, 4, 2 bp; each returns the central ceil(1000/r) bins."""

    def __init__(self, width=DEC_WIDTH, resolutions=AUX_RES):
        super().__init__()
        self.resolutions = resolutions
        self.convs = nn.ModuleList([nn.Conv1d(width, 1, 1) for _ in resolutions])
        for c in self.convs:
            nn.init.zeros_(c.weight)
            nn.init.zeros_(c.bias)

    def forward(self, hs):
        out = []
        for conv, h, r in zip(self.convs, hs, self.resolutions):
            n = -(-OUT_LEN // r)
            start = (h.shape[-1] - n) // 2
            out.append(conv(h)[..., start:start + n])
        return out


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.aux_heads = AuxProfileHeads()
        self.progress, self.epoch = 0.0, 0

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        hs = self.decoder(z, skips)
        profile = self.profile_head(hs[-1])
        out = {"profile": profile, "counts": counts}
        if self.training:
            out["aux"] = self.aux_heads(hs[:-1])
        return out


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's Kendall-Gal profile MNLL + count MSE, plus deep supervision: MNLL of the zero-initialised auxiliary
    profile heads (16, 8, 4, 2 bp) against the targets summed into those bins, mean over heads, weight 0.5."""

    AUX_RES = (16, 8, 4, 2)
    AUX_WEIGHT = 0.5

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def forward(self, out, y, is_peak, net):
        profile_loss = mnll(out["profile"], y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        loss = profile_loss / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        logs = {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach()}
        aux = out.get("aux") if isinstance(out, dict) else None
        if aux:
            yf = y.float()
            terms = []
            for logits, r in zip(aux, self.AUX_RES):
                n = logits.shape[-1]
                pad = n * r - yf.shape[-1]
                yt = torch.nn.functional.pad(yf, (pad // 2, pad - pad // 2)) if pad > 0 else yf
                yt = yt.reshape(yt.shape[0], yt.shape[1], n, r).sum(-1)
                terms.append(mnll(logits.float(), yt).mean())
            aux_loss = sum(terms) / len(terms)
            loss = loss + self.AUX_WEIGHT * aux_loss
            logs["aux_mnll"] = aux_loss.detach()
        return loss.sum(), logs

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
ENC_DILATIONS = ((1, 2, 4, 8), (1, 2), (1, 2), (1, 2), (1, 2))
DEC_DILATIONS = ((1,), (1,), (1,), (1,), (1, 2))   # coarse -> fine


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class GatedResBlock(nn.Module):
    """WaveNet gated residual block, pre-norm: GN -> dilated k=3 conv C->2C -> tanh(a)*sigmoid(b) (float32) -> dropout ->
    linear C->C, added back with a per-channel layer scale (init 0.1). The conv kernel is stored as a 2-D matrix so Muon
    trains it."""

    def __init__(self, channels, dilation=1, k=3, dropout=0.1, scale=0.1):
        super().__init__()
        self.c, self.k, self.dilation = channels, k, dilation
        self.norm = group_norm(channels)
        self.weight = nn.Parameter(torch.empty(2 * channels, channels * k))
        nn.init.trunc_normal_(self.weight, std=(1.0 / (channels * k)) ** 0.5)
        self.bias = nn.Parameter(torch.zeros(2 * channels))
        self.drop = nn.Dropout(dropout)
        self.out = nn.Linear(channels, channels, bias=True)
        nn.init.trunc_normal_(self.out.weight, std=0.02)
        nn.init.zeros_(self.out.bias)
        self.gamma = nn.Parameter(torch.full((channels,), scale))

    def forward(self, x):
        h = self.norm(x)
        w = self.weight.view(2 * self.c, self.c, self.k)
        pad = self.dilation * (self.k - 1) // 2
        h = F.conv1d(h, w.to(h.dtype), self.bias.to(h.dtype), padding=pad, dilation=self.dilation)
        a, g = h.float().chunk(2, dim=1)
        h = (torch.tanh(a) * torch.sigmoid(g)).to(x.dtype)
        h = self.drop(h)
        h = self.out(h.transpose(1, 2)).transpose(1, 2)
        return x + h * self.gamma.to(h.dtype).view(1, -1, 1)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    """CAPYBARA pre-activation conv block: norm -> GELU -> dropout -> conv."""

    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    """CAPYBARA HybridAttentionUnit: a residual pair of conv blocks, then pre-norm multi-head self-attention and an MLP."""

    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, dilations=ENC_DILATIONS):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([nn.Sequential(*[GatedResBlock(width, d) for d in ds]) for ds in dilations])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.max_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.entry = GatedResBlock(width, 1)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.entry(x))


class YCountHead(nn.Module):
    """CAPYBARA YCountHead: conv [128, 64] (kernel 5, GroupNorm, GELU, dropout, max-pool 2), adaptive average pool to 4
    bins, MLP [64] with LayerNorm, then one output: ln(total counts + 1)."""

    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    """up + 2*sigmoid(W[up; skip])*skip, W a zero-initialised kernel-1 conv, so the gate starts at 1."""

    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    """Transposed-conv (k=2, s=2) upsampling cropped to the skip length, gated-add skip fusion, WaveNet gated blocks."""

    def __init__(self, width=WIDTH, dilations=DEC_DILATIONS):
        super().__init__()
        n = len(dilations)
        self.up = nn.ModuleList([nn.ConvTranspose1d(width, width, 2, stride=2) for _ in range(n)])
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n)])
        self.blocks = nn.ModuleList([nn.Sequential(*[GatedResBlock(width, d) for d in ds]) for ds in dilations])

    def forward(self, z, skips):
        x = z
        for up, fuse, blocks, skip in zip(self.up, self.fuse, self.blocks, reversed(skips)):
            x = up(x)
            L = skip.shape[-1]
            if x.shape[-1] < L:
                x = F.pad(x, (0, L - x.shape[-1]))
            x = x[..., :L]
            x = blocks(fuse(x, skip))
        return x


class ProfileHead(nn.Module):
    """Nonlinear profile head: k=1 conv to 64, GELU, then a k=75 conv; the central 1,000 positions."""

    def __init__(self, width=WIDTH, hidden=64, k=75):
        super().__init__()
        self.proj = nn.Conv1d(width, hidden, 1)
        self.conv = nn.Conv1d(hidden, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(F.gelu(self.proj(h)))[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        profile = self.profile_head(self.decoder(z, skips))
        return {"profile": profile, "counts": counts}


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's training loss (cherimoya.py fit + losses._mixture_loss): profile MNLL and count MSE on ln(total + 1),
    weighted by Kendall-Gal learned weights 1 / (2 s^2) with the regulariser (log s)^2. As in cherimoya, the weights stop
    learning after the first epoch in which the mean absolute gradient of s0 falls below 1."""

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def forward(self, out, y, is_peak, net):
        """`out` is the model's output dict, y (B, 1, 1000) raw targets, is_peak (B,) bool. Returns (loss, logs)."""
        profile_loss = mnll(out["profile"], y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        loss = profile_loss / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        return loss.sum(), {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach()}

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5
AUX_RES = (16, 8, 4, 2)


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block (cherimoya/cheri.py at 8e4283f, pure PyTorch)."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):                      # x: (B, C, L)
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    """CAPYBARA pre-activation conv block: norm -> GELU -> dropout -> conv."""

    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    """CAPYBARA HybridAttentionUnit: a residual pair of conv blocks, then pre-norm multi-head self-attention and an MLP."""

    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([CheriBlock(width) for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    """CAPYBARA YCountHead."""

    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    """up + 2*sigmoid(W[up; skip])*skip, W a zero-initialised kernel-1 conv, so the gate starts at 1."""

    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    """Returns the base-resolution output and the outputs of the coarser stages (16, 8, 4, 2 bp) for deep supervision."""

    def __init__(self, width=WIDTH, n_stages=N_STAGES, blocks_per_stage=2):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[CheriBlock(width) for _ in range(blocks_per_stage)])
                                     for _ in range(n_stages)])

    def forward(self, z, skips):
        x = z
        outs = []
        for fuse, blocks, skip in zip(self.fuse, self.blocks, reversed(skips)):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = blocks(fuse(x, skip))
            outs.append(x)
        return x, outs[:-1]


class ProfileHead(nn.Module):
    """Cherimoya's profile head: one kernel-75 conv, then the central 1,000 positions."""

    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.aux_heads = nn.ModuleList([nn.Conv1d(WIDTH, 1, 1) for _ in AUX_RES])
        for head in self.aux_heads:
            nn.init.zeros_(head.weight)
            nn.init.zeros_(head.bias)
        self.progress, self.epoch = 0.0, 0

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        h, stages = self.decoder(z, skips)
        profile = self.profile_head(h)
        start = (x.shape[-1] - OUT_LEN) // 2
        aux = []
        for head, s, r in zip(self.aux_heads, stages, AUX_RES):
            off = start % r
            n = (off + OUT_LEN + r - 1) // r
            st = start // r
            aux.append(head(s)[..., st:st + n].float())
        return {"profile": profile, "counts": counts, "aux": aux}


def build_model():
    return CAPY()

# --- block: objective ---
AUX_RES_OBJ = (16, 8, 4, 2)
AUX_WEIGHT = 0.5
IN_LEN_OBJ = 2114


class Objective(nn.Module):
    """Cherimoya's training loss (profile MNLL + count MSE with Kendall-Gal learned weights), plus deep supervision: MNLL of
    zero-initialised aux profile heads on decoder stages at 16/8/4/2 bp against the targets summed into those bins, mean over
    heads, weight 0.5, scaled by the (detached) profile weight."""

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def forward(self, out, y, is_peak, net):
        profile_loss = mnll(out["profile"], y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        loss = profile_loss / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        logs = {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach()}
        aux = out.get("aux", None)
        if aux:
            start = (IN_LEN_OBJ - y.shape[-1]) // 2
            yf = y.float()
            total = 0.0
            for logits, r in zip(aux, AUX_RES_OBJ):
                off = start % r
                n = logits.shape[-1]
                pad_r = n * r - off - yf.shape[-1]
                yb = torch.nn.functional.pad(yf, (off, pad_r)).reshape(yf.shape[0], 1, n, r).sum(-1)
                total = total + mnll(logits.float(), yb).mean()
            aux_loss = total / len(aux)
            loss = loss + AUX_WEIGHT * aux_loss / (2 * self.s0.detach() ** 2)
            logs["aux_mnll"] = aux_loss.detach()
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        return loss.sum(), logs

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5
DETACH_START = 0.72
DETACH_END = 0.80


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block (cherimoya/cheri.py at 8e4283f, pure PyTorch): a 3-tap dilated depthwise conv, a per-example
    layer norm over the whole (length, channel) plane, then an MLP (C -> 2C -> C, tanh GELU) added back with scale 0.15."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):                      # x: (B, C, L)
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    """CAPYBARA pre-activation conv block: norm -> GELU -> dropout -> conv."""

    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    """CAPYBARA HybridAttentionUnit: a residual pair of conv blocks, then pre-norm multi-head self-attention and an MLP."""

    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([CheriBlock(width) for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    """CAPYBARA YCountHead: conv [128, 64] (kernel 5, GroupNorm, GELU, dropout, max-pool 2), adaptive average pool to 4
    bins, MLP [64] with LayerNorm, then one output: ln(total counts + 1)."""

    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    """up + 2*sigmoid(W[up; skip])*skip, W a zero-initialised kernel-1 conv, so the gate starts at 1."""

    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES, blocks_per_stage=2):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[CheriBlock(width) for _ in range(blocks_per_stage)])
                                     for _ in range(n_stages)])

    def forward(self, z, skips):
        x = z
        for fuse, blocks, skip in zip(self.fuse, self.blocks, reversed(skips)):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = blocks(fuse(x, skip))
        return x


class ProfileHead(nn.Module):
    """Cherimoya's profile head: one kernel-75 conv, then the central 1,000 positions."""

    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    """Baseline CAPY plus a late count-trunk detach: the count head reads z.detach() + g*(z - z.detach()) (same values as z),
    so from DETACH_START to DETACH_END of training the count loss's gradient into the shared trunk fades from 1 to 0 while
    the count head itself keeps training. g lives in a buffer set by the `progress` setter, so torch.compile sees no
    changing Python constant."""

    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.register_buffer("detach_gate", torch.ones(()), persistent=False)
        self._progress = 0.0
        self.epoch = 0

    @property
    def progress(self):
        return self._progress

    @progress.setter
    def progress(self, value):
        value = float(value)
        self._progress = value
        g = (DETACH_END - value) / (DETACH_END - DETACH_START)
        g = min(1.0, max(0.0, g))
        with torch.no_grad():
            self.detach_gate.fill_(g)

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        zd = z.detach()
        zc = zd + self.detach_gate.to(z.dtype) * (z - zd)
        counts = self.count_head(zc)
        profile = self.profile_head(self.decoder(z, skips))
        return {"profile": profile, "counts": counts}


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's training loss (cherimoya.py fit + losses._mixture_loss): profile MNLL and count MSE on ln(total + 1),
    weighted by Kendall-Gal learned weights 1 / (2 s^2) with the regulariser (log s)^2. As in cherimoya, the weights stop
    learning after the first epoch in which the mean absolute gradient of s0 falls below 1."""

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def forward(self, out, y, is_peak, net):
        """`out` is the model's output dict, y (B, 1, 1000) raw targets, is_peak (B,) bool. Returns (loss, logs)."""
        profile_loss = mnll(out["profile"], y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        loss = profile_loss / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        return loss.sum(), {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach()}

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

