        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    """Baseline CAPY plus a late count-trunk detach: the count head reads z.detach() + g*(z - z.detach()), so its value is
    always z, but from DETACH_START of training the count loss's gradient into the shared trunk is ramped from 1 to 0.
    g lives in a buffer set through the `progress` property, so torch.compile does not recompile as it changes."""

    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.register_buffer("count_gate", torch.ones(()))
        self._progress = 0.0
        self.epoch = 0

    @property
    def progress(self):
        return self._progress

    @progress.setter
    def progress(self, value):
        value = float(value)
        self._progress = value
        g = 1.0 - (value - DETACH_START) / (DETACH_END - DETACH_START)
        g = min(1.0, max(0.0, g))
        if "count_gate" in self._buffers:
            self.count_gate.fill_(g)

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        g = self.count_gate.to(z.dtype)
        zd = z.detach()
        counts = self.count_head(zd + g * (z - zd))
        profile = self.profile_head(self.decoder(z, skips))
        return {"profile": profile, "counts": counts}


