WIDTH = 256
N_STAGES = 5
DETACH_START, DETACH_RAMP = 0.72, 0.10


class CheriBlock(nn.Module):
    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


class InvolutionCheriBlock(nn.Module):
    """Cheri skeleton with an involution token mixer: a static k-tap depthwise kernel plus a dynamic kernel generated per
    position from the input (Linear C -> C/r -> G*k, zero-initialised, so the block starts as a static-kernel Cheri), shared
    within each of G channel groups. Then the per-example plane norm (float32) and the C -> 2C -> C MLP, residual 0.15."""

    def __init__(self, channels, k=5, groups=16, reduction=4, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.k, self.groups, self.residual_scale, self.eps = k, groups, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(k, channels))
        self.gen1 = nn.Linear(channels, max(16, channels // reduction))
        self.gen2 = nn.Linear(max(16, channels // reduction), groups * k)
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.gen1.weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)
        nn.init.zeros_(self.gen1.bias)
        nn.init.zeros_(self.gen2.weight)
        nn.init.zeros_(self.gen2.bias)

    def forward(self, x):
        b, c, length = x.shape
        k, g = self.k, self.groups
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=k // 2, groups=c)
        dyn = self.gen2(F.gelu(self.gen1(x.transpose(1, 2)), approximate="tanh"))        # (B, L, G*k)
        dyn = dyn.reshape(b, length, g, k).permute(0, 2, 1, 3).to(x.dtype)                # (B, G, L, k)
        patches = F.pad(x, (k // 2, k // 2)).unfold(2, k, 1)                              # (B, C, L, k)
        patches = patches.reshape(b, g, c // g, length, k)
        y = y + torch.einsum("bgclk,bglk->bgcl", patches, dyn).reshape(b, c, length).to(y.dtype)
        flat = y.reshape(b, -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    def __init__(self, cin, cout, k, dilation=1):
