        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([CheriBlock(width) for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    """Returns (final base-resolution features, list of per-stage outputs from coarsest to finest)."""

    def __init__(self, width=WIDTH, n_stages=N_STAGES, blocks_per_stage=2):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[CheriBlock(width) for _ in range(blocks_per_stage)])
                                     for _ in range(n_stages)])

    def forward(self, z, skips):
        x = z
        stages = []
        for fuse, blocks, skip in zip(self.fuse, self.blocks, reversed(skips)):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = blocks(fuse(x, skip))
            stages.append(x)
        return x, stages


class ProfileHead(nn.Module):
    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class AuxProfileHead(nn.Module):
    """Zero-initialised kernel-1 readout at a coarse decoder stage. Its bin logits are repeated over the bases each bin
    covers (pooling bins start at position 0) and cropped to the central OUT_LEN bases, so a softmax over them is the
    binned distribution spread uniformly within bins: MNLL on raw base counts then trains it like binned MNLL."""

    def __init__(self, width, factor):
        super().__init__()
        self.factor = factor
        self.conv = nn.Conv1d(width, 1, 1)
        nn.init.zeros_(self.conv.weight)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h, full_len):
        logits = self.conv(h).float()
        logits = torch.repeat_interleave(logits, self.factor, dim=-1)[..., :full_len]
        start = (full_len - OUT_LEN) // 2
        return logits[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    """Baseline CAPY with a late count-trunk detach (g: 1 -> 0 between 72% and 82% of training) plus decoder deep
    supervision: auxiliary profile heads on the decoder stages at 16, 8, 4 and 2 bp, used only in training."""

    def __init__(self):
        super().__init__()
        self.register_buffer("count_gate", torch.ones(()), persistent=False)
        self._progress = 0.0
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.aux_heads = nn.ModuleList([AuxProfileHead(WIDTH, 2 ** (N_STAGES - 1 - i)) for i in range(AUX_STAGES)])
        self.progress, self.epoch = 0.0, 0

    @property
    def progress(self):
        return self._progress

    @progress.setter
    def progress(self, p):
        self._progress = float(p)
        g = min(1.0, max(0.0, 1.0 - (float(p) - DETACH_START) / DETACH_RAMP))
        if "count_gate" in self._buffers:
            self._buffers["count_gate"].fill_(g)

    def forward(self, x):
        full_len = x.shape[-1]
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        zd = z.detach()
        counts = self.count_head(zd + self.count_gate.to(z.dtype) * (z - zd))
        h, stages = self.decoder(z, skips)
        profile = self.profile_head(h)
        out = {"profile": profile, "counts": counts}
        if self.training:
            out["aux_profiles"] = [head(s, full_len) for head, s in zip(self.aux_heads, stages)]
        return out


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's training loss (profile MNLL + count MSE on ln(total + 1), Kendall-Gal learned weights 1 / (2 s^2) with
    the regulariser (log s)^2, frozen after the first epoch in which the mean |grad s0| < 1), plus decoder deep
    supervision: 0.5 x the mean MNLL of the auxiliary profile heads, scaled by the profile weight with s0 detached so the
    learned balance is set by the main losses only."""

    AUX_WEIGHT = 0.5

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def forward(self, out, y, is_peak, net):
        profile_loss = mnll(out["profile"], y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        loss = profile_loss / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        logs = {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach()}
        aux = out.get("aux_profiles") if isinstance(out, dict) else None
        if aux:
            aux_loss = torch.stack([mnll(a.float(), y).mean() for a in aux]).mean()
            loss = loss + self.AUX_WEIGHT * aux_loss / (2 * self.s0.detach() ** 2)
            logs["aux_mnll"] = aux_loss.detach()
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        return loss.sum(), logs

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5
WINDOW = 32
HEADS = 8
DETACH_START, DETACH_RAMP = 0.72, 0.10


class CheriBlock(nn.Module):
    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class LocalAttnBlock(nn.Module):
    """Swin-style 1-D block: depthwise k3 conditional position encoding, then GN pre-norm multi-head self-attention inside
    non-overlapping windows of WINDOW positions (optionally shifted by half a window), with a learned relative-position
    bias and float32 scores/softmax; padded keys are masked. Then GN pre-norm MLP C->2C->C. Residuals use layer scale."""

    def __init__(self, channels, window=WINDOW, heads=HEADS, shift=False, expansion=2, layer_scale=0.1):
        super().__init__()
        self.window, self.heads, self.shift = window, heads, shift
        self.cpe = nn.Conv1d(channels, channels, 3, padding=1, groups=channels)
        nn.init.trunc_normal_(self.cpe.weight, std=0.02)
        nn.init.zeros_(self.cpe.bias)
        self.norm1 = group_norm(channels)
        self.qkv = nn.Linear(channels, 3 * channels, bias=False)
        self.out = nn.Linear(channels, channels)
        self.rel = nn.Parameter(torch.zeros(heads, 2 * window - 1))
        idx = torch.arange(window)
        self.register_buffer("rel_idx", idx[:, None] - idx[None, :] + window - 1, persistent=False)
        self.norm2 = group_norm(channels)
        self.fc1 = nn.Linear(channels, expansion * channels)
        self.fc2 = nn.Linear(expansion * channels, channels)
        for w in (self.qkv.weight, self.out.weight, self.fc1.weight, self.fc2.weight):
            nn.init.trunc_normal_(w, std=0.02)
        for b in (self.out.bias, self.fc1.bias, self.fc2.bias):
            nn.init.zeros_(b)
        self.g1 = nn.Parameter(torch.full((channels, 1), layer_scale))
        self.g2 = nn.Parameter(torch.full((channels, 1), layer_scale))

    def attend(self, x):                       # x: (B, C, L)
        B, C, L = x.shape
        W, h = self.window, self.heads
        d = C // h
        off = W // 2 if self.shift else 0
        right = (-(L + off)) % W
        xp = F.pad(x, (off, right)).transpose(1, 2)          # (B, Lp, C)
        Lp = xp.shape[1]
        n = Lp // W
        qkv = self.qkv(xp).reshape(B, n, W, 3, h, d).permute(3, 0, 1, 4, 2, 5)   # (3, B, n, h, W, d)
        q, k, v = qkv[0], qkv[1], qkv[2]
        s = torch.matmul(q.float(), k.float().transpose(-1, -2)) * (d ** -0.5)
        s = s + self.rel[:, self.rel_idx].float()
        valid = F.pad(torch.ones(L, device=x.device, dtype=torch.float32), (off, right)).reshape(1, n, 1, 1, W)
        s = s + (1.0 - valid) * -1e4
        p = torch.softmax(s, dim=-1).to(v.dtype)
        o = torch.matmul(p, v)                                # (B, n, h, W, d)
        o = o.permute(0, 1, 3, 2, 4).reshape(B, Lp, C)[:, off:off + L]
        return self.out(o).transpose(1, 2)

    def forward(self, x):
        x = x + self.cpe(x)
        a = self.attend(self.norm1(x))
        x = x + self.g1.to(a.dtype) * a.to(x.dtype) if x.dtype == a.dtype else x + (self.g1 * a).to(x.dtype)
        y = self.norm2(x).transpose(1, 2)
        y = self.fc2(F.gelu(self.fc1(y), approximate="tanh")).transpose(1, 2)
        return x + (self.g2 * y).to(x.dtype)


class StandardizedConv1d(nn.Conv1d):
    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([LocalAttnBlock(width, shift=(i % 2 == 1)) for i in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(LocalAttnBlock(width, shift=False), LocalAttnBlock(width, shift=True))
                                     for _ in range(n_stages)])

    def forward(self, z, skips):
        x = z
        for fuse, blocks, skip in zip(self.fuse, self.blocks, reversed(skips)):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = blocks(fuse(x, skip))
        return x


class ProfileHead(nn.Module):
    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    """Shifted-window local-attention Y-net with the C15 bottleneck, count head, gated skips, profile head and late
    count-trunk detach (g 1 -> 0 between 72% and 82% of training, held in a buffer set by the progress setter)."""

    def __init__(self):
        super().__init__()
        self.register_buffer("count_gate", torch.ones(()), persistent=False)
        self._progress = 0.0
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0

    @property
    def progress(self):
        return self._progress

    @progress.setter
    def progress(self, p):
        self._progress = float(p)
        g = min(1.0, max(0.0, 1.0 - (float(p) - DETACH_START) / DETACH_RAMP))
        if "count_gate" in self._buffers:
            self._buffers["count_gate"].fill_(g)

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        zd = z.detach()
        counts = self.count_head(zd + self.count_gate.to(z.dtype) * (z - zd))
        profile = self.profile_head(self.decoder(z, skips))
        return {"profile": profile, "counts": counts}


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's training loss (cherimoya.py fit + losses._mixture_loss): profile MNLL and count MSE on ln(total + 1),
    weighted by Kendall-Gal learned weights 1 / (2 s^2) with the regulariser (log s)^2. As in cherimoya, the weights stop
    learning after the first epoch in which the mean absolute gradient of s0 falls below 1."""

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def forward(self, out, y, is_peak, net):
        """`out` is the model's output dict, y (B, 1, 1000) raw targets, is_peak (B,) bool. Returns (loss, logs)."""
        profile_loss = mnll(out["profile"], y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        loss = profile_loss / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        return loss.sum(), {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach()}

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block: 3-tap dilated depthwise conv, whole-plane layer norm, MLP C->2C->C added with scale 0.15."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


class InceptionBlock(nn.Module):
    """Inception block: depthwise branches (k3, k9, k19, k3 d4) and a max-pool branch, concat, float32 plane norm, GELU,
    5C -> C linear, added back with scale 0.15."""

    BRANCHES = ((3, 1), (9, 1), (19, 1), (3, 4))

    def __init__(self, channels, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.residual_scale, self.eps = residual_scale, eps
        self.weights = nn.ParameterList([nn.Parameter(torch.empty(k, channels)) for k, _ in self.BRANCHES])
        n = len(self.BRANCHES) + 1
        self.proj = nn.Linear(n * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in self.weights:
            nn.init.trunc_normal_(w, std=0.02)
        nn.init.trunc_normal_(self.proj.weight, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        outs = []
        for (k, d), w in zip(self.BRANCHES, self.weights):
            outs.append(F.conv1d(x, w.t().unsqueeze(1).to(x.dtype), padding=d * (k - 1) // 2, dilation=d, groups=c))
        outs.append(F.max_pool1d(x, 3, stride=1, padding=1))
        y = torch.cat(outs, 1)
        shape = y.shape
        flat = y.reshape(shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = self.activation(y.reshape(shape).to(x.dtype)).transpose(1, 2)
        y = self.proj(y).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    """CAPYBARA pre-activation conv block: norm -> GELU -> dropout -> conv."""

    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    """CAPYBARA HybridAttentionUnit: residual pair of conv blocks, then pre-norm self-attention and an MLP."""

    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([InceptionBlock(width) for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class MultiQueryAttentionPool(nn.Module):
    """Q learned queries, each a zero-initialised kernel-1 score over positions; float32 softmax over all positions;
    output (B, C*Q) in the same (C, Q) flatten order as adaptive pooling to Q bins."""

    def __init__(self, channels, queries=4):
        super().__init__()
        self.score = nn.Conv1d(channels, queries, 1)
        nn.init.zeros_(self.score.weight)
        nn.init.zeros_(self.score.bias)

    def forward(self, h):
        w = torch.softmax(self.score(h).float(), dim=-1)
        pooled = torch.einsum("bcl,bql->bcq", h.float(), w)
        return pooled.flatten(1).to(h.dtype)


class YCountHead(nn.Module):
    """YCountHead: conv [128, 64] (k5, GN, GELU, dropout, max-pool 2), then a 4-query attention pool (from L10/C13)
    instead of the adaptive average pool, MLP [64] with LayerNorm, one output ln(total + 1)."""

    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, queries=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs = nn.Sequential(*layers)
        self.pool = MultiQueryAttentionPool(c, queries)
        layers, d = [], c * queries
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(self.pool(self.convs(z)))


class GatedSkipFusion(nn.Module):
    """up + 2*sigmoid(W[up; skip])*skip, W a zero-initialised kernel-1 conv, so the gate starts at 1."""

    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES, blocks_per_stage=2):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[InceptionBlock(width) for _ in range(blocks_per_stage)])
                                     for _ in range(n_stages)])

    def forward(self, z, skips):
        x = z
        for fuse, blocks, skip in zip(self.fuse, self.blocks, reversed(skips)):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = blocks(fuse(x, skip))
        return x


class ProfileHead(nn.Module):
    """Cherimoya's profile head: one kernel-75 conv, then the central 1,000 positions."""

    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0

    def forward(self, x):
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        counts = self.count_head(z)
        profile = self.profile_head(self.decoder(z, skips))
        return {"profile": profile, "counts": counts}


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's training loss: profile MNLL and count MSE on ln(total + 1), weighted by Kendall-Gal learned weights
    1 / (2 s^2) with the regulariser (log s)^2; the weights stop learning after the first epoch in which the mean absolute
    gradient of s0 falls below 1."""

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def forward(self, out, y, is_peak, net):
        profile_loss = mnll(out["profile"], y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        loss = profile_loss / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        return loss.sum(), {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach()}

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5
BLOCKS_PER_STAGE = 2
DILATIONS = (1, 2, 4, 8)
RES_SCALE = 0.2
DETACH_START = 0.72
DETACH_END = 0.82


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block (used only at the start of the baseline bottleneck)."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class MatConv1d(nn.Module):
    """'Same' dense conv whose weight is stored as a 2-D (cout, cin*k) matrix, so Muon optimises it."""

    def __init__(self, cin, cout, k, dilation=1, bias=True):
        super().__init__()
        self.cin, self.cout, self.k, self.dilation = cin, cout, k, dilation
        self.weight = nn.Parameter(torch.empty(cout, cin * k))
        nn.init.normal_(self.weight, std=1.0 / math.sqrt(cin * k))
        self.bias = nn.Parameter(torch.zeros(cout)) if bias else None

    def forward(self, x):
        w = self.weight.view(self.cout, self.cin, self.k).to(x.dtype)
        b = self.bias.to(x.dtype) if self.bias is not None else None
        return F.conv1d(x, w, b, padding=self.dilation * (self.k - 1) // 2, dilation=self.dilation)


class DilatedResBlock(nn.Module):
    """Pre-activation residual block: GN, GELU, k=3 dilated conv, GN, GELU, k=1 conv, scaled residual add."""

    def __init__(self, channels, dilation, scale=RES_SCALE):
        super().__init__()
        self.norm1, self.norm2 = group_norm(channels), group_norm(channels)
        self.conv1 = MatConv1d(channels, channels, 3, dilation)
        self.conv2 = MatConv1d(channels, channels, 1)
        self.scale = scale

    def forward(self, x):
        y = self.conv1(F.gelu(self.norm1(x)))
        y = self.conv2(F.gelu(self.norm2(y)))
        return x + self.scale * y


def stage_blocks(width, stage):
    return nn.Sequential(*[DilatedResBlock(width, DILATIONS[(BLOCKS_PER_STAGE * stage + j) % len(DILATIONS)])
                           for j in range(BLOCKS_PER_STAGE)])


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.stages = nn.ModuleList([stage_blocks(width, s) for s in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for stage in self.stages:
            x = stage(x)
            skips.append(x)
            x = F.max_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class TransposedUp(nn.Module):
    """Transposed conv k=2, s=2 written as a per-position Linear(C, 2C) plus interleave (2-D weight for Muon)."""

    def __init__(self, width=WIDTH):
        super().__init__()
        self.lin = nn.Linear(width, 2 * width)

    def forward(self, x):
        b, c, l = x.shape
        y = self.lin(x.transpose(1, 2))
        return y.reshape(b, l, 2, c).reshape(b, 2 * l, c).transpose(1, 2)


class ConcatFusion(nn.Module):
    def __init__(self, width=WIDTH):
        super().__init__()
        self.proj = MatConv1d(2 * width, width, 1)

    def forward(self, up, skip):
        return self.proj(torch.cat([up, skip], 1))


class Decoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.up = nn.ModuleList([TransposedUp(width) for _ in range(n_stages)])
        self.fuse = nn.ModuleList([ConcatFusion(width) for _ in range(n_stages)])
        self.stages = nn.ModuleList([stage_blocks(width, s) for s in range(n_stages)])
        self.aux_heads = nn.ModuleList([nn.Conv1d(width, 1, 1) for _ in range(n_stages - 1)])
        for h in self.aux_heads:
            nn.init.zeros_(h.weight)
            nn.init.zeros_(h.bias)

    def forward(self, z, skips):
        x, aux = z, []
        for i, (up, fuse, stage, skip) in enumerate(zip(self.up, self.fuse, self.stages, reversed(skips))):
            u = up(x)[..., :skip.shape[-1]]
            x = stage(fuse(u, skip))
            if self.training and i < len(self.aux_heads):
                aux.append(self.aux_heads[i](x))
        return x, aux


class ProfileHead(nn.Module):
    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0

    def count_gate(self):
        p = float(self.progress)
        if p <= DETACH_START:
            return 1.0
        if p >= DETACH_END:
            return 0.0
        return round(1.0 - (p - DETACH_START) / (DETACH_END - DETACH_START), 2)

    def forward(self, x):
        in_len = x.shape[-1]
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        g = self.count_gate()
        if g >= 1.0:
            zc = z
        elif g <= 0.0:
            zc = z.detach()
        else:
            zd = z.detach()
            zc = zd + g * (z - zd)
        counts = self.count_head(zc)
        h, aux = self.decoder(z, skips)
        profile = self.profile_head(h)
        out = {"profile": profile, "counts": counts}
        if aux:
            start = (in_len - OUT_LEN) // 2
            aux_full = []
            for i, a in enumerate(aux):
                r = 2 ** (N_STAGES - 1 - i)
                aux_full.append(a.repeat_interleave(r, dim=-1)[..., start:start + OUT_LEN])
            out["aux_profiles"] = aux_full
        return out


def build_model():
    return CAPY()

# --- block: objective ---
DS_WEIGHT = 0.5


class Objective(nn.Module):
    """Cherimoya's Kendall-Gal weighted MNLL + count MSE, plus deep supervision: MNLL of the decoder's coarse-stage
    logits (16/8/4/2 bp, repeated to base resolution, which gives the same gradient as MNLL on binned counts),
    averaged over stages and added to the profile loss with weight DS_WEIGHT."""

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))

    def forward(self, out, y, is_peak, net):
        profile_loss = mnll(out["profile"].float(), y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        logs = {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach()}
        profile_term = profile_loss
        aux = out.get("aux_profiles", None)
        if aux:
            ds = sum(mnll(a.float(), y).mean() for a in aux) / len(aux)
            profile_term = profile_term + DS_WEIGHT * ds
            logs["aux_mnll"] = ds.detach()
        loss = profile_term / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        return loss.sum(), logs

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5
AUX_STAGES = 4      # decoder stages at 16, 8, 4, 2 bp get auxiliary profile heads
RNN_STAGES = (4,)   # encoder stage at 16 bp gets a recurrent unit after its Cheri block


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block: 3-tap dilated depthwise conv, whole-plane layer norm, MLP C->2C->C added with scale 0.15."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    """CAPYBARA pre-activation conv block: norm -> GELU -> dropout -> conv."""

    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class BiLSTMMixer(nn.Module):
    """Pre-norm bidirectional LSTM residual branch on (B, C, L), computed in float32 with autocast off, then a linear
    projection and a per-channel layer scale (init 0.1). Then a pre-norm GELU MLP (C -> 2C -> C), also with layer scale 0.1."""

    def __init__(self, channels, mlp_ratio=2, dropout=0.1, layer_scale=0.1):
        super().__init__()
        assert channels % 2 == 0
        self.norm1 = nn.LayerNorm(channels)
        self.rnn = nn.LSTM(channels, channels // 2, num_layers=1, batch_first=True, bidirectional=True)
        self.proj = nn.Linear(channels, channels)
        self.norm2 = nn.LayerNorm(channels)
        hidden = int(channels * mlp_ratio)
        self.mlp = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(approximate="tanh"), nn.Dropout(dropout),
                                 nn.Linear(hidden, channels))
        self.drop = nn.Dropout(dropout)
        self.gamma1 = nn.Parameter(torch.full((channels,), layer_scale))
        self.gamma2 = nn.Parameter(torch.full((channels,), layer_scale))
        for name, p in self.rnn.named_parameters():
            if "weight_ih" in name:
                nn.init.xavier_uniform_(p)
            elif "weight_hh" in name:
                nn.init.orthogonal_(p)
            elif "bias" in name:
                nn.init.zeros_(p)
                h = p.shape[0] // 4
                with torch.no_grad():
                    p[h:2 * h].fill_(0.5)   # mild forget-gate bias (two bias vectors per direction add up to 1)
        for lin in (self.proj, self.mlp[0], self.mlp[3]):
            nn.init.trunc_normal_(lin.weight, std=0.02)
            nn.init.zeros_(lin.bias)

    def forward(self, x):                      # x: (B, C, L)
        h = x.transpose(1, 2).float()          # (B, L, C), residual stream in float32
        with torch.autocast(device_type=x.device.type, enabled=False):
            y, _ = self.rnn(self.norm1(h))
        h = h + self.gamma1 * self.drop(self.proj(y)).float()
        h = h + self.gamma2 * self.drop(self.mlp(self.norm2(h))).float()
        return h.transpose(1, 2)


class RecurrentUnit(nn.Module):
    """HybridAttentionUnit with the self-attention replaced by a bidirectional LSTM: a residual pair of conv blocks
    (scaled at 0.2), then the BiLSTM mixer and its MLP."""

    def __init__(self, channels, k=5, dropout=0.1, conv_scale=0.2):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.conv_scale = conv_scale
        self.mixer = BiLSTMMixer(channels, dropout=dropout)

    def forward(self, x):
        x = x + self.conv_scale * self.conv2(self.conv1(x))
        return self.mixer(x)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES, rnn_stages=RNN_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([nn.Sequential(CheriBlock(width), BiLSTMMixer(width)) if i in rnn_stages
                                     else CheriBlock(width) for i in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    """Cheri block, then recurrent units (conv pair + BiLSTM + MLP) instead of attention units."""

    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[RecurrentUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    """CAPYBARA YCountHead: conv [128, 64] (k5, GN, GELU, dropout, max-pool 2), adaptive avg pool to 4 bins, MLP [64]."""

    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    """up + 2*sigmoid(W[up; skip])*skip, W a zero-initialised kernel-1 conv, so the gate starts at 1."""

    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    """Baseline decoder; the first AUX_STAGES stages (16, 8, 4, 2 bp) also emit zero-initialised kernel-1 profile logits."""

    def __init__(self, width=WIDTH, n_stages=N_STAGES, blocks_per_stage=2, aux_stages=AUX_STAGES):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[CheriBlock(width) for _ in range(blocks_per_stage)])
                                     for _ in range(n_stages)])
        self.aux_heads = nn.ModuleList()
        for _ in range(aux_stages):
            head = nn.Conv1d(width, 1, 1)
            nn.init.zeros_(head.weight)
            nn.init.zeros_(head.bias)
            self.aux_heads.append(head)
        self.n_stages = n_stages

    def forward(self, z, skips):
        x = z
        aux = []
        for i, (fuse, blocks, skip) in enumerate(zip(self.fuse, self.blocks, reversed(skips))):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = blocks(fuse(x, skip))
            if i < len(self.aux_heads):
                res = 2 ** (self.n_stages - 1 - i)
                aux.append((res, self.aux_heads[i](x)))
        return x, aux


class ProfileHead(nn.Module):
    """Cherimoya's profile head: one kernel-75 conv, then the central 1,000 positions."""

    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0
        # late count-trunk detach gate g (1 -> 0); set by the Objective from net.progress
        self.register_buffer("count_gate", torch.ones(1), persistent=False)

    def forward(self, x):
        in_len = x.shape[-1]
        flank = (in_len - OUT_LEN) // 2
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        zd = z.detach()
        z_c = zd + self.count_gate.to(z.dtype) * (z - zd)
        counts = self.count_head(z_c)
        h, aux = self.decoder(z, skips)
        out = {"profile": self.profile_head(h), "counts": counts}
        for res, logits in aux:
            b0 = flank // res
            b1 = -(-(flank + OUT_LEN) // res)
            out["aux_%d" % res] = logits[..., b0:b1]
        return out


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Cherimoya's Kendall-Gal loss (profile MNLL + count MSE on ln(total+1), peaks and non-peaks alike) plus decoder deep
    supervision: MNLL of the auxiliary 16/8/4/2 bp logits against the targets summed into the same bins (total weight 0.5,
    added to the profile term). Also drives the model's late count-trunk detach gate g: 1 until progress 0.72, linearly
    to 0 at 0.85. Ends with the required non-finite guard."""

    AUX_WEIGHT = 0.5
    FLANK = 557
    DETACH_START, DETACH_END = 0.72, 0.85

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))
        self._last_gate = None

    def _binned(self, y, res, n_bins):
        left = self.FLANK % res
        right = n_bins * res - left - y.shape[-1]
        yp = nn.functional.pad(y.float(), (left, max(right, 0)))[..., :n_bins * res]
        return yp.reshape(y.shape[0], y.shape[1], n_bins, res).sum(-1)

    def _set_gate(self, net):
        p = float(getattr(net, "progress", 0.0))
        g = min(1.0, max(0.0, (self.DETACH_END - p) / (self.DETACH_END - self.DETACH_START)))
        if self._last_gate is not None and g == self._last_gate:
            return g
        gate = getattr(net, "count_gate", None)
        if gate is None and hasattr(net, "_orig_mod"):
            gate = getattr(net._orig_mod, "count_gate", None)
        if gate is not None:
            gate.data.fill_(g)
        self._last_gate = g
        return g

    def forward(self, out, y, is_peak, net):
        g = self._set_gate(net)
        profile_loss = mnll(out["profile"].float(), y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        aux_keys = [k for k in out if isinstance(k, str) and k.startswith("aux_")]
        aux_loss = torch.zeros((), device=profile_loss.device)
        for k in aux_keys:
            res = int(k[4:])
            logits = out[k].float()
            aux_loss = aux_loss + mnll(logits, self._binned(y, res, logits.shape[-1])).mean()
        if aux_keys:
            aux_loss = aux_loss / len(aux_keys)
        prof_term = profile_loss + self.AUX_WEIGHT * aux_loss
        loss = prof_term / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        loss = loss.sum()
        logs = {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach(),
                "aux_mnll": aux_loss.detach(), "count_gate": torch.tensor(g)}
        # Non-finite guard: one fp16 batch that overflows must not end the run. The batch counts as loss 0 and its
        # non-finite gradients make the loss scaler skip the step. 50 in a row means the weights really diverged:
        # the true loss is returned and the trainer stops the run.
        finite = torch.isfinite(loss)
        if bool(finite):
            self._nonfinite_streak = 0
        else:
            self._nonfinite_streak = getattr(self, "_nonfinite_streak", 0) + 1
            if self._nonfinite_streak < 50:
                loss = torch.where(finite, loss, torch.zeros_like(loss))
                logs = {k: torch.nan_to_num(torch.as_tensor(v, dtype=torch.float32), nan=0.0, posinf=0.0, neginf=0.0)
                        for k, v in logs.items()}
        return loss, logs

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5
AUX_STAGES = 4   # decoder stages at 16, 8, 4, 2 bp get auxiliary profile heads
ENC_DILATIONS = (1, 2, 4)
DEC_DILATIONS = (1, 2)


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class FP32GroupNorm(nn.GroupNorm):
    """GroupNorm with statistics computed in float32."""

    def forward(self, x):
        return F.group_norm(x.float(), self.num_groups, self.weight.float(), self.bias.float(), self.eps).to(x.dtype)


def fp32_group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return FP32GroupNorm(groups, channels)


class DilatedResBlock(nn.Module):
    """Basenji-style dense dilated residual block, pre-activation: GN(fp32) -> GELU -> dense k3 dilated conv ->
    GN(fp32) -> GELU -> dropout -> kernel-1 conv, added back with a per-channel layer scale initialised at 0.1."""

    def __init__(self, channels, dilation=1, k=3, dropout=0.1, layer_scale=0.1):
        super().__init__()
        self.norm1 = fp32_group_norm(channels)
        self.conv1 = nn.Conv1d(channels, channels, k, padding=dilation * (k - 1) // 2, dilation=dilation)
        self.norm2 = fp32_group_norm(channels)
        self.drop = nn.Dropout(dropout)
        self.conv2 = nn.Conv1d(channels, channels, 1)
        self.act = nn.GELU(approximate="tanh")
        self.gamma = nn.Parameter(torch.full((1, channels, 1), layer_scale))
        for conv in (self.conv1, self.conv2):
            fan_in = conv.in_channels * conv.kernel_size[0]
            nn.init.trunc_normal_(conv.weight, std=1.0 / math.sqrt(fan_in))
            nn.init.zeros_(conv.bias)

    def forward(self, x):
        y = self.conv1(self.act(self.norm1(x)))
        y = self.conv2(self.drop(self.act(self.norm2(y))))
        return x + self.gamma.to(x.dtype) * y


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block: 3-tap dilated depthwise conv, whole-plane layer norm, MLP C->2C->C added with scale 0.15."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    """CAPYBARA pre-activation conv block: norm -> GELU -> dropout -> conv."""

    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    """CAPYBARA HybridAttentionUnit: residual pair of conv blocks, then pre-norm self-attention and an MLP."""

    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    """Stem k21, then per stage a dilated residual tower (dilations 1, 2, 4), skip, average pool 2."""

    def __init__(self, width=WIDTH, n_stages=N_STAGES, dilations=ENC_DILATIONS):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([nn.Sequential(*[DilatedResBlock(width, d) for d in dilations])
                                     for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    """CAPYBARA YCountHead: conv [128, 64] (k5, GN, GELU, dropout, max-pool 2), adaptive avg pool to 4 bins, MLP [64]."""

    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    """up + 2*sigmoid(W[up; skip])*skip, W a zero-initialised kernel-1 conv, so the gate starts at 1."""

    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    """Gated skip fusion then a dilated residual pair (dilations 1, 2) per stage; the first AUX_STAGES stages
    (16, 8, 4, 2 bp) also emit zero-initialised kernel-1 profile logits for deep supervision."""

    def __init__(self, width=WIDTH, n_stages=N_STAGES, dilations=DEC_DILATIONS, aux_stages=AUX_STAGES):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[DilatedResBlock(width, d) for d in dilations])
                                     for _ in range(n_stages)])
        self.aux_heads = nn.ModuleList()
        for _ in range(aux_stages):
            head = nn.Conv1d(width, 1, 1)
            nn.init.zeros_(head.weight)
            nn.init.zeros_(head.bias)
            self.aux_heads.append(head)
        self.n_stages = n_stages

    def forward(self, z, skips):
        x = z
        aux = []
        for i, (fuse, blocks, skip) in enumerate(zip(self.fuse, self.blocks, reversed(skips))):
            x = F.interpolate(x, size=skip.shape[-1], mode="nearest")
            x = blocks(fuse(x, skip))
            if i < len(self.aux_heads):
                res = 2 ** (self.n_stages - 1 - i)
                aux.append((res, self.aux_heads[i](x)))
        return x, aux


class ProfileHead(nn.Module):
    """Cherimoya's profile head: one kernel-75 conv, then the central 1,000 positions."""

    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0
        # late count-trunk detach gate g (1 -> 0); set by the Objective from net.progress
        self.register_buffer("count_gate", torch.ones(1), persistent=False)

    def forward(self, x):
        in_len = x.shape[-1]
        flank = (in_len - OUT_LEN) // 2
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        zd = z.detach()
        z_c = zd + self.count_gate.to(z.dtype) * (z - zd)
        counts = self.count_head(z_c)
        h, aux = self.decoder(z, skips)
        out = {"profile": self.profile_head(h), "counts": counts}
        for res, logits in aux:
            b0 = flank // res
            b1 = -(-(flank + OUT_LEN) // res)
            out["aux_%d" % res] = logits[..., b0:b1]
        return out


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """Kendall-Gal loss (profile MNLL + count MSE on ln(total+1), counts on peaks and non-peaks) plus decoder deep
    supervision (aux 16/8/4/2 bp MNLL on bin-summed targets, weight 0.5). Drives the late count-trunk detach gate g:
    1 until progress 0.72, linearly to 0 at 0.85. Ends with the non-finite guard."""

    AUX_WEIGHT = 0.5
    FLANK = 557
    DETACH_START, DETACH_END = 0.72, 0.85

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))
        self._last_gate = None

    def _binned(self, y, res, n_bins):
        left = self.FLANK % res
        right = n_bins * res - left - y.shape[-1]
        yp = nn.functional.pad(y.float(), (left, max(right, 0)))[..., :n_bins * res]
        return yp.reshape(y.shape[0], y.shape[1], n_bins, res).sum(-1)

    def _set_gate(self, net):
        p = float(getattr(net, "progress", 0.0))
        g = min(1.0, max(0.0, (self.DETACH_END - p) / (self.DETACH_END - self.DETACH_START)))
        if self._last_gate is not None and g == self._last_gate:
            return g
        gate = getattr(net, "count_gate", None)
        if gate is None and hasattr(net, "_orig_mod"):
            gate = getattr(net._orig_mod, "count_gate", None)
        if gate is not None:
            gate.data.fill_(g)
        self._last_gate = g
        return g

    def forward(self, out, y, is_peak, net):
        g = self._set_gate(net)
        profile_loss = mnll(out["profile"].float(), y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        aux_keys = [k for k in out if isinstance(k, str) and k.startswith("aux_")]
        aux_loss = torch.zeros((), device=profile_loss.device)
        for k in aux_keys:
            res = int(k[4:])
            logits = out[k].float()
            aux_loss = aux_loss + mnll(logits, self._binned(y, res, logits.shape[-1])).mean()
        if aux_keys:
            aux_loss = aux_loss / len(aux_keys)
        prof_term = profile_loss + self.AUX_WEIGHT * aux_loss
        loss = prof_term / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        loss = loss.sum()
        logs = {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach(),
                "aux_mnll": aux_loss.detach(), "count_gate": torch.tensor(g)}
        # Non-finite guard: one fp16 batch that overflows must not end the run. The batch counts as loss 0 and its
        # non-finite gradients make the loss scaler skip the step. 50 in a row means the weights really diverged:
        # the true loss is returned and the trainer stops the run.
        finite = torch.isfinite(loss)
        if bool(finite):
            self._nonfinite_streak = 0
        else:
            self._nonfinite_streak = getattr(self, "_nonfinite_streak", 0) + 1
            if self._nonfinite_streak < 50:
                loss = torch.where(finite, loss, torch.zeros_like(loss))
                logs = {k: torch.nan_to_num(torch.as_tensor(v, dtype=torch.float32), nan=0.0, posinf=0.0, neginf=0.0)
                        for k, v in logs.items()}
        return loss, logs

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
import torch.utils.checkpoint as _ckpt

WIDTH = 256
N_STAGES = 5
AUX_STAGES = 4   # decoder column at 16, 8, 4, 2 bp gets auxiliary profile heads


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block: 3-tap dilated depthwise conv, whole-plane layer norm, MLP C->2C->C added with scale 0.15."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


class InceptionBlock(nn.Module):
    """C4 inception block: depthwise k3/k9/k19/k3-dil4 branches plus max-pool, concat, float32 plane norm, GELU,
    5C->C linear, residual scale 0.15."""

    BRANCHES = ((3, 1), (9, 1), (19, 1), (3, 4))

    def __init__(self, channels, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.residual_scale, self.eps = residual_scale, eps
        self.weights = nn.ParameterList([nn.Parameter(torch.empty(k, channels)) for k, _ in self.BRANCHES])
        n = len(self.BRANCHES) + 1
        self.proj = nn.Linear(n * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in self.weights:
            nn.init.trunc_normal_(w, std=0.02)
        nn.init.trunc_normal_(self.proj.weight, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        outs = []
        for (k, d), w in zip(self.BRANCHES, self.weights):
            outs.append(F.conv1d(x, w.t().unsqueeze(1).to(x.dtype), padding=d * (k - 1) // 2, dilation=d, groups=c))
        outs.append(F.max_pool1d(x, 3, stride=1, padding=1))
        y = torch.cat(outs, 1)
        shape = y.shape
        flat = y.reshape(shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = self.activation(y.reshape(shape).to(x.dtype)).transpose(1, 2)
        y = self.proj(y).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class ConvBlock(nn.Module):
    """CAPYBARA pre-activation conv block: norm -> GELU -> dropout -> conv."""

    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    """CAPYBARA HybridAttentionUnit: residual pair of conv blocks, then pre-norm self-attention and an MLP."""

    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    """Stem conv k21, one inception block per stage (1, 2, 4, 8, 16 bp), average-pool 2 between stages."""

    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([InceptionBlock(width) for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=4):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    """CAPYBARA YCountHead: conv [128, 64] (k5, GN, GELU, dropout, max-pool 2), adaptive avg pool to 4 bins, MLP [64]."""

    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class NestedFusion(nn.Module):
    """U-Net++ dense node input: the mean of the newest same-level node and the upsampled lower node, plus a
    zero-initialised kernel-1 projection of the concatenation of ALL same-level nodes and the upsampled node
    (so at init it is a plain additive skip, and the dense path is learned)."""

    def __init__(self, n_inputs, width=WIDTH):
        super().__init__()
        self.mix = nn.Conv1d(n_inputs * width, width, 1)
        nn.init.zeros_(self.mix.weight)
        nn.init.zeros_(self.mix.bias)

    def forward(self, same_level, up):
        base = 0.5 * (same_level[-1] + up)
        return base + self.mix(torch.cat(list(same_level) + [up], 1))


class NestedNode(nn.Module):
    """One U-Net++ node: dense fusion then inception block(s)."""

    def __init__(self, n_inputs, width=WIDTH, n_blocks=1):
        super().__init__()
        self.fuse = NestedFusion(n_inputs, width)
        self.blocks = nn.Sequential(*[InceptionBlock(width) for _ in range(n_blocks)])

    def forward(self, up, *same_level):
        return self.blocks(self.fuse(same_level, up))


def _run(node, up, same_level):
    # activation checkpointing during training: only the node output is kept, its internals are recomputed in backward
    if torch.is_grad_enabled() and node.training:
        return _ckpt.checkpoint(node, up, *same_level, use_reentrant=False)
    return node(up, *same_level)


class NestedDecoder(nn.Module):
    """U-Net++ decoder. Level i (0 = 1 bp ... 4 = 16 bp) holds nodes X[i][0] = encoder skip and intermediate nodes
    X[i][j] = Inception(NestedFusion(X[i][0..j-1], up(X[i+1][j-1]))) for j < N_STAGES - i, built from the encoder
    skips only. The decoder column then climbs from the bottleneck: at level i it fuses all X[i][*] with the upsampled
    column output and applies two inception blocks. The column stages at 16, 8, 4, 2 bp emit zero-initialised
    kernel-1 profile logits for deep supervision. All nodes are activation-checkpointed in training to fit memory."""

    def __init__(self, width=WIDTH, n_stages=N_STAGES, blocks_per_stage=2, aux_stages=AUX_STAGES):
        super().__init__()
        self.n = n_stages
        self.inter = nn.ModuleDict()
        for j in range(1, n_stages):
            for i in range(0, n_stages - j):
                self.inter["%d_%d" % (i, j)] = NestedNode(j + 1, width, 1)
        self.column = nn.ModuleList([NestedNode(s + 2, width, blocks_per_stage) for s in range(n_stages)])
        self.aux_heads = nn.ModuleList()
        for _ in range(aux_stages):
            head = nn.Conv1d(width, 1, 1)
            nn.init.zeros_(head.weight)
            nn.init.zeros_(head.bias)
            self.aux_heads.append(head)

    def forward(self, z, skips):
        n = self.n
        nodes = [[s] for s in skips]
        for j in range(1, n):
            for i in range(0, n - j):
                key = "%d_%d" % (i, j)
                up = F.interpolate(nodes[i + 1][j - 1], size=skips[i].shape[-1], mode="nearest")
                nodes[i].append(_run(self.inter[key], up, nodes[i]))
        x = z
        aux = []
        for s in range(n):
            i = n - 1 - s
            up = F.interpolate(x, size=skips[i].shape[-1], mode="nearest")
            x = _run(self.column[s], up, nodes[i])
            if s < len(self.aux_heads):
                aux.append((2 ** i, self.aux_heads[s](x)))
        return x, aux


class ProfileHead(nn.Module):
    """Cherimoya's profile head: one kernel-75 conv, then the central 1,000 positions."""

    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = NestedDecoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0
        # late count-trunk detach gate g (1 -> 0); set by the Objective from net.progress
        self.register_buffer("count_gate", torch.ones(1), persistent=False)

    def forward(self, x):
        in_len = x.shape[-1]
        flank = (in_len - OUT_LEN) // 2
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        zd = z.detach()
        z_c = zd + self.count_gate.to(z.dtype) * (z - zd)
        counts = self.count_head(z_c)
        h, aux = self.decoder(z, skips)
        out = {"profile": self.profile_head(h), "counts": counts}
        for res, logits in aux:
            b0 = flank // res
            b1 = -(-(flank + OUT_LEN) // res)
            out["aux_%d" % res] = logits[..., b0:b1]
        return out


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    '''Cherimoya's Kendall-Gal loss (profile MNLL + count MSE on ln(total+1), peaks and non-peaks alike) plus decoder deep
    supervision (MNLL of the 16/8/4/2 bp aux logits against bin-summed targets, weight 0.5). Drives the late count-trunk
    detach gate g: 1 until progress 0.72, linearly to 0 at 0.85. Ends with the non-finite guard.'''

    AUX_WEIGHT = 0.5
    FLANK = 557
    DETACH_START, DETACH_END = 0.72, 0.85

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))
        self._last_gate = None

    def _binned(self, y, res, n_bins):
        left = self.FLANK % res
        right = n_bins * res - left - y.shape[-1]
        yp = nn.functional.pad(y.float(), (left, max(right, 0)))[..., :n_bins * res]
        return yp.reshape(y.shape[0], y.shape[1], n_bins, res).sum(-1)

    def _set_gate(self, net):
        p = float(getattr(net, 'progress', 0.0))
        g = min(1.0, max(0.0, (self.DETACH_END - p) / (self.DETACH_END - self.DETACH_START)))
        if self._last_gate is not None and g == self._last_gate:
            return g
        gate = getattr(net, 'count_gate', None)
        if gate is None and hasattr(net, '_orig_mod'):
            gate = getattr(net._orig_mod, 'count_gate', None)
        if gate is not None:
            gate.data.fill_(g)
        self._last_gate = g
        return g

    def forward(self, out, y, is_peak, net):
        g = self._set_gate(net)
        profile_loss = mnll(out['profile'].float(), y).mean()
        count_loss = ((log_total(y) - out['counts'].float()) ** 2).mean()
        aux_keys = [k for k in out if isinstance(k, str) and k.startswith('aux_')]
        aux_loss = torch.zeros((), device=profile_loss.device)
        for k in aux_keys:
            res = int(k[4:])
            logits = out[k].float()
            aux_loss = aux_loss + mnll(logits, self._binned(y, res, logits.shape[-1])).mean()
        if aux_keys:
            aux_loss = aux_loss / len(aux_keys)
        prof_term = profile_loss + self.AUX_WEIGHT * aux_loss
        loss = prof_term / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        loss = loss.sum()
        logs = {'profile_mnll': profile_loss.detach(), 'count_mse': count_loss.detach(),
                'aux_mnll': aux_loss.detach(), 'count_gate': torch.tensor(g)}
        # Non-finite guard: one fp16 batch that overflows must not end the run. The batch counts as loss 0 and its
        # non-finite gradients make the loss scaler skip the step. 50 in a row means the weights really diverged:
        # the true loss is returned and the trainer stops the run.
        finite = torch.isfinite(loss)
        if bool(finite):
            self._nonfinite_streak = 0
        else:
            self._nonfinite_streak = getattr(self, '_nonfinite_streak', 0) + 1
            if self._nonfinite_streak < 50:
                loss = torch.where(finite, loss, torch.zeros_like(loss))
                logs = {k: torch.nan_to_num(torch.as_tensor(v, dtype=torch.float32), nan=0.0, posinf=0.0, neginf=0.0)
                        for k, v in logs.items()}
        return loss, logs

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)

# --- block: model ---
WIDTH = 256
N_STAGES = 5
AUX_STAGES = 4          # decoder stages at 16, 8, 4, 2 bp get auxiliary profile heads
ENC_DILATIONS = (1, 2)  # dilation of the two dense layers in each encoder block
DEC_DILATIONS = ((1, 2), (1, 4))  # the two dense blocks per decoder stage


class CheriBlock(nn.Module):
    """Cherimoya's Cheri block: 3-tap dilated depthwise conv, whole-plane layer norm, MLP C->2C->C added with scale 0.15."""

    def __init__(self, channels, dilation=1, expansion=2, residual_scale=0.15, eps=1e-3):
        super().__init__()
        self.dilation, self.residual_scale, self.eps = dilation, residual_scale, eps
        self.conv_weight = nn.Parameter(torch.empty(3, channels))
        self.linear1 = nn.Linear(channels, expansion * channels, bias=False)
        self.linear2 = nn.Linear(expansion * channels, channels, bias=False)
        self.activation = nn.GELU(approximate="tanh")
        for w in (self.conv_weight, self.linear1.weight, self.linear2.weight):
            nn.init.trunc_normal_(w, std=0.02)

    def forward(self, x):
        c = x.shape[1]
        y = F.conv1d(x, self.conv_weight.t().unsqueeze(1).to(x.dtype), padding=self.dilation, dilation=self.dilation, groups=c)
        flat = y.reshape(y.shape[0], -1).float()
        y = ((flat - flat.mean(1, keepdim=True)) * (flat.var(1, keepdim=True, unbiased=False) + self.eps).rsqrt())
        y = y.reshape(x.shape).to(x.dtype).transpose(1, 2)
        y = self.linear2(self.activation(self.linear1(y))).transpose(1, 2)
        return x + y * self.residual_scale


def group_norm(channels, groups=8):
    while channels % groups:
        groups -= 1
    return nn.GroupNorm(groups, channels)


def gn32(norm, x):
    """GroupNorm with statistics in float32 (autocast off), returned in the input dtype."""
    with torch.autocast(device_type=x.device.type, enabled=False):
        y = norm(x.float())
    return y.to(x.dtype)


class StandardizedConv1d(nn.Conv1d):
    """CAPYBARA's weight-standardised 'same' convolution."""

    def __init__(self, cin, cout, k, dilation=1):
        super().__init__(cin, cout, k, padding=0, dilation=dilation, bias=True)
        self.scale = nn.Parameter(torch.ones(cout, 1, 1))

    def forward(self, x):
        w = self.weight
        var = w.var(dim=(1, 2), unbiased=False, keepdim=True)
        fan_in = self.in_channels * self.kernel_size[0]
        w = (w - w.mean(dim=(1, 2), keepdim=True)) * torch.rsqrt(torch.clamp(var * fan_in, min=1e-4)) * self.scale
        total = self.dilation[0] * (self.kernel_size[0] - 1)
        x = F.pad(x, (total // 2, total - total // 2))
        return F.conv1d(x, w.to(x.dtype), self.bias.to(x.dtype), dilation=self.dilation)


class RepDenseLayer(nn.Module):
    """Pre-activation RepVGG-style dense layer: fp32 GroupNorm -> GELU -> (full k3 dilated conv + full 1x1 conv), both
    weight-standardised so the output scale stays bounded whatever the optimiser does to the raw weights."""

    def __init__(self, channels, dilation=1, k=3):
        super().__init__()
        self.norm = group_norm(channels)
        self.conv_k = StandardizedConv1d(channels, channels, k, dilation)
        self.conv_1 = StandardizedConv1d(channels, channels, 1)
        for conv in (self.conv_k, self.conv_1):
            nn.init.zeros_(conv.bias)
        with torch.no_grad():
            self.conv_1.scale.fill_(0.5)

    def forward(self, x):
        h = F.gelu(gn32(self.norm, x), approximate="tanh")
        return self.conv_k(h) + self.conv_1(h)


class RepDenseBlock(nn.Module):
    """Residual block of two RepDense layers (dropout between), per-channel layer scale 0.1 and drop-path."""

    def __init__(self, channels, dilations=(1, 2), dropout=0.1, drop_path=0.1, layer_scale=0.1):
        super().__init__()
        self.layer1 = RepDenseLayer(channels, dilations[0])
        self.layer2 = RepDenseLayer(channels, dilations[1])
        self.drop = nn.Dropout(dropout)
        self.drop_path = drop_path
        self.gamma = nn.Parameter(torch.full((channels, 1), layer_scale))

    def forward(self, x):
        y = self.layer2(self.drop(self.layer1(x)))
        y = y * self.gamma.to(y.dtype)
        if self.training and self.drop_path > 0:
            keep = 1.0 - self.drop_path
            mask = (torch.rand(x.shape[0], 1, 1, device=x.device) < keep).to(y.dtype) / keep
            y = y * mask
        return x + y


class ConvBlock(nn.Module):
    """CAPYBARA pre-activation conv block: norm -> GELU -> dropout -> conv."""

    def __init__(self, channels, k, dropout=0.1):
        super().__init__()
        self.norm, self.act, self.drop = group_norm(channels), nn.GELU(), nn.Dropout(dropout)
        self.conv = StandardizedConv1d(channels, channels, k)

    def forward(self, x):
        return self.conv(self.drop(self.act(self.norm(x))))


class HybridAttentionUnit(nn.Module):
    """CAPYBARA HybridAttentionUnit: residual pair of conv blocks, then pre-norm self-attention and an MLP."""

    def __init__(self, channels, k=5, heads=4, mlp_ratio=2.0, dropout=0.1, attn_dropout=0.1):
        super().__init__()
        self.conv1, self.conv2 = ConvBlock(channels, k, dropout), ConvBlock(channels, k, dropout)
        self.attn_norm = group_norm(channels)
        self.attn = nn.MultiheadAttention(channels, heads, dropout=attn_dropout, batch_first=True)
        hidden = max(channels, int(channels * mlp_ratio))
        self.ffn_norm = group_norm(channels)
        self.ffn = nn.Sequential(nn.Linear(channels, hidden), nn.GELU(), nn.Dropout(dropout), nn.Linear(hidden, channels),
                                 nn.Dropout(dropout))

    def forward(self, x):
        x = x + self.conv2(self.conv1(x))
        y = self.attn_norm(x).transpose(1, 2)
        x = x + self.attn(y, y, y, need_weights=False)[0].transpose(1, 2)
        return x + self.ffn(self.ffn_norm(x).transpose(1, 2)).transpose(1, 2)


class Encoder(nn.Module):
    def __init__(self, width=WIDTH, n_stages=N_STAGES):
        super().__init__()
        self.stem = nn.Conv1d(4, width, 21, padding=10)
        nn.init.trunc_normal_(self.stem.weight, std=0.02)
        nn.init.zeros_(self.stem.bias)
        self.blocks = nn.ModuleList([RepDenseBlock(width, ENC_DILATIONS) for _ in range(n_stages)])

    def forward(self, x):
        x = F.gelu(self.stem(x), approximate="tanh")
        skips = []
        for block in self.blocks:
            x = block(x)
            skips.append(x)
            x = F.avg_pool1d(x, 2, ceil_mode=True)
        return x, skips


class Bottleneck(nn.Module):
    def __init__(self, width=WIDTH, depth=3):
        super().__init__()
        self.cheri = CheriBlock(width)
        self.units = nn.Sequential(*[HybridAttentionUnit(width) for _ in range(depth)])

    def forward(self, x):
        return self.units(self.cheri(x))


class YCountHead(nn.Module):
    """CAPYBARA YCountHead: conv [128, 64] (k5, GN, GELU, dropout, max-pool 2), adaptive avg pool to 4 bins, MLP [64]."""

    def __init__(self, width=WIDTH, convs=(128, 64), mlp=(64,), k=5, bins=4, dropout=0.1):
        super().__init__()
        layers, c = [], width
        for h in convs:
            layers += [nn.Conv1d(c, h, k, padding=k // 2, bias=False), group_norm(h), nn.GELU(), nn.Dropout(dropout),
                       nn.MaxPool1d(2, ceil_mode=True)]
            c = h
        self.convs, self.bins = nn.Sequential(*layers), bins
        layers, d = [], c * bins
        for h in mlp:
            layers += [nn.Linear(d, h), nn.LayerNorm(h), nn.GELU(), nn.Dropout(dropout)]
            d = h
        self.mlp = nn.Sequential(*layers, nn.Linear(d, 1))

    def forward(self, z):
        return self.mlp(F.adaptive_avg_pool1d(self.convs(z), self.bins).flatten(1))


class GatedSkipFusion(nn.Module):
    """up + 2*sigmoid(W[up; skip])*skip, W a zero-initialised kernel-1 conv, so the gate starts at 1."""

    def __init__(self, width=WIDTH):
        super().__init__()
        self.gate = nn.Conv1d(2 * width, width, 1)
        nn.init.zeros_(self.gate.weight)
        nn.init.zeros_(self.gate.bias)

    def forward(self, up, skip):
        return up + 2 * torch.sigmoid(self.gate(torch.cat([up, skip], 1))) * skip


class Decoder(nn.Module):
    """Dense RepVGG decoder (2 blocks per stage); the first AUX_STAGES stages (16, 8, 4, 2 bp) emit zero-init logits."""

    def __init__(self, width=WIDTH, n_stages=N_STAGES, aux_stages=AUX_STAGES):
        super().__init__()
        self.fuse = nn.ModuleList([GatedSkipFusion(width) for _ in range(n_stages)])
        self.blocks = nn.ModuleList([nn.Sequential(*[RepDenseBlock(width, d) for d in DEC_DILATIONS])
                                     for _ in range(n_stages)])
        self.aux_heads = nn.ModuleList()
        for _ in range(aux_stages):
            head = nn.Conv1d(width, 1, 1)
            nn.init.zeros_(head.weight)
            nn.init.zeros_(head.bias)
            self.aux_heads.append(head)
        self.n_stages = n_stages

    def forward(self, z, skips):
        x = z
        aux = []
        for i, (fuse, blocks, skip) in enumerate(zip(self.fuse, self.blocks, reversed(skips))):
            x = F.interpolate(x.to(skip.dtype), size=skip.shape[-1], mode="nearest")
            x = blocks(fuse(x, skip))
            if i < len(self.aux_heads):
                res = 2 ** (self.n_stages - 1 - i)
                aux.append((res, self.aux_heads[i](x)))
        return x, aux


class ProfileHead(nn.Module):
    """Cherimoya's profile head: one kernel-75 conv, then the central 1,000 positions."""

    def __init__(self, width=WIDTH, k=75):
        super().__init__()
        self.conv = nn.Conv1d(width, 1, k, padding=k // 2)
        nn.init.trunc_normal_(self.conv.weight, std=0.02)
        nn.init.zeros_(self.conv.bias)

    def forward(self, h):
        start = (h.shape[-1] - OUT_LEN) // 2
        return self.conv(h)[..., start:start + OUT_LEN]


class CAPY(nn.Module):
    def __init__(self):
        super().__init__()
        self.encoder = Encoder()
        self.bottleneck = Bottleneck()
        self.count_head = YCountHead()
        self.decoder = Decoder()
        self.profile_head = ProfileHead()
        self.progress, self.epoch = 0.0, 0
        # late count-trunk detach gate g (1 -> 0); set by the Objective from net.progress
        self.register_buffer("count_gate", torch.ones(1), persistent=False)

    def forward(self, x):
        in_len = x.shape[-1]
        flank = (in_len - OUT_LEN) // 2
        z0, skips = self.encoder(x)
        z = self.bottleneck(z0)
        zd = z.detach()
        z_c = zd + self.count_gate.to(z.dtype) * (z - zd)
        counts = self.count_head(z_c)
        h, aux = self.decoder(z, skips)
        out = {"profile": self.profile_head(h), "counts": counts}
        for res, logits in aux:
            b0 = flank // res
            b1 = -(-(flank + OUT_LEN) // res)
            out["aux_%d" % res] = logits[..., b0:b1]
        return out


def build_model():
    return CAPY()

# --- block: objective ---
class Objective(nn.Module):
    """C8's loss: Kendall-Gal weighted profile MNLL + count MSE on ln(total+1) over peaks and non-peaks, plus decoder deep
    supervision (aux 16/8/4/2 bp MNLL on bin-summed targets, weight 0.5, added to the profile term). Drives the model's late
    count-trunk detach gate g: 1 until progress 0.72, linearly to 0 at 0.85. Ends with the required non-finite guard."""

    AUX_WEIGHT = 0.5
    FLANK = 557
    DETACH_START, DETACH_END = 0.72, 0.85

    def __init__(self):
        super().__init__()
        self.s0 = nn.Parameter(torch.ones(1))
        self.s1 = nn.Parameter(torch.ones(1))
        self._last_gate = None

    def _binned(self, y, res, n_bins):
        left = self.FLANK % res
        right = n_bins * res - left - y.shape[-1]
        yp = nn.functional.pad(y.float(), (left, max(right, 0)))[..., :n_bins * res]
        return yp.reshape(y.shape[0], y.shape[1], n_bins, res).sum(-1)

    def _set_gate(self, net):
        p = float(getattr(net, "progress", 0.0))
        g = min(1.0, max(0.0, (self.DETACH_END - p) / (self.DETACH_END - self.DETACH_START)))
        if self._last_gate is not None and g == self._last_gate:
            return g
        gate = getattr(net, "count_gate", None)
        if gate is None and hasattr(net, "_orig_mod"):
            gate = getattr(net._orig_mod, "count_gate", None)
        if gate is not None:
            gate.data.fill_(g)
        self._last_gate = g
        return g

    def forward(self, out, y, is_peak, net):
        g = self._set_gate(net)
        profile_loss = mnll(out["profile"].float(), y).mean()
        count_loss = ((log_total(y) - out["counts"].float()) ** 2).mean()
        aux_keys = [k for k in out if isinstance(k, str) and k.startswith("aux_")]
        aux_loss = torch.zeros((), device=profile_loss.device)
        for k in aux_keys:
            res = int(k[4:])
            logits = out[k].float()
            aux_loss = aux_loss + mnll(logits, self._binned(y, res, logits.shape[-1])).mean()
        if aux_keys:
            aux_loss = aux_loss / len(aux_keys)
        prof_term = profile_loss + self.AUX_WEIGHT * aux_loss
        loss = prof_term / (2 * self.s0 ** 2) + count_loss / (2 * self.s1 ** 2)
        if self.s0.requires_grad:
            loss = loss + torch.log(self.s0) ** 2 + torch.log(self.s1) ** 2
        loss = loss.sum()
        logs = {"profile_mnll": profile_loss.detach(), "count_mse": count_loss.detach(),
                "aux_mnll": aux_loss.detach(), "count_gate": torch.tensor(g)}
        # Non-finite guard: one fp16 batch that overflows must not end the run. The batch counts as loss 0 and its
        # non-finite gradients make the loss scaler skip the step. 50 in a row means the weights really diverged:
        # the true loss is returned and the trainer stops the run.
        finite = torch.isfinite(loss)
        if bool(finite):
            self._nonfinite_streak = 0
        else:
            self._nonfinite_streak = getattr(self, "_nonfinite_streak", 0) + 1
            if self._nonfinite_streak < 50:
                loss = torch.where(finite, loss, torch.zeros_like(loss))
                logs = {k: torch.nan_to_num(torch.as_tensor(v, dtype=torch.float32), nan=0.0, posinf=0.0, neginf=0.0)
                        for k, v in logs.items()}
        return loss, logs

    def end_epoch(self, epoch):
        if self.s0.requires_grad and self.s0.grad is not None and float(self.s0.grad.abs().mean()) < 1:
            self.s0.requires_grad_(False)
            self.s1.requires_grad_(False)
